CREATE OR REPLACE FUNCTION private.dashboard143_touch_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE changed boolean;
BEGIN
 IF TG_OP='UPDATE' THEN
  changed:=(OLD.service_date,OLD.driver_id,OLD.route_id,OLD.vehicle_id,OLD.is_rental,OLD.attendance_category,OLD.attendance_slot_index,OLD.dispatcher_notes,OLD.status::text='cancelled')
   IS DISTINCT FROM (NEW.service_date,NEW.driver_id,NEW.route_id,NEW.vehicle_id,NEW.is_rental,NEW.attendance_category,NEW.attendance_slot_index,NEW.dispatcher_notes,NEW.status::text='cancelled');
  IF (OLD.service_date,OLD.driver_id) IS DISTINCT FROM (NEW.service_date,NEW.driver_id)
  THEN PERFORM private.dashboard143_touch(OLD.service_date,OLD.driver_id,true);END IF;
  PERFORM private.dashboard143_touch(NEW.service_date,NEW.driver_id,changed);RETURN NEW;
 ELSIF TG_OP='DELETE' THEN PERFORM private.dashboard143_touch(OLD.service_date,OLD.driver_id,true);RETURN OLD;
 ELSE PERFORM private.dashboard143_touch(NEW.service_date,NEW.driver_id,true);RETURN NEW;END IF;
END;$function$

CREATE OR REPLACE FUNCTION private.dashboard146_guard_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j jsonb; oldj jsonb; d date; oldd date;
BEGIN
 IF TG_OP<>'DELETE' THEN j:=to_jsonb(NEW);END IF;
 IF TG_OP<>'INSERT' THEN oldj:=to_jsonb(OLD);END IF;
 IF TG_TABLE_NAME='daily_run_observations' THEN
  SELECT service_date INTO d FROM public.runs WHERE id=(j->>'run_id')::bigint;
  SELECT service_date INTO oldd FROM public.runs WHERE id=(oldj->>'run_id')::bigint;
 ELSIF TG_TABLE_NAME='v055_driver_work_completions' THEN
  SELECT service_date INTO d FROM public.v055_run_work WHERE id=(j->>'work_id')::bigint;
  SELECT service_date INTO oldd FROM public.v055_run_work WHERE id=(oldj->>'work_id')::bigint;
 ELSE d:=(j->>'service_date')::date;oldd:=(oldj->>'service_date')::date;END IF;
 IF (d IS NOT NULL AND private.dashboard146_is_closed(d)) OR (oldd IS NOT NULL AND private.dashboard146_is_closed(oldd))
 THEN RAISE EXCEPTION '此日期已結案，請先由主管填寫原因重新開啟';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION private.dashboard147_monthly(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 day date; finish date; event_row record; normalized jsonb; cache jsonb:='{}';
 deliveries jsonb:='[]'; shifts jsonb:='[]'; work_rows jsonb:='[]'; attendance_rows jsonb:='[]'; original_runs jsonb:='[]'; dates jsonb:='[]';
 rows_for_date jsonb; closed boolean; reopened bigint; stamp jsonb;
BEGIN
 IF NOT private.can_manage_finance() THEN RAISE EXCEPTION '僅 Brian 可查看月度報表' USING ERRCODE='42501'; END IF;
 IF p_month IS NULL OR extract(day from p_month)<>1 THEN RAISE EXCEPTION '請提供月份第一日'; END IF;
 finish:=(p_month+interval '1 month')::date;
 FOR day IN SELECT generate_series(p_month,finish-1,interval '1 day')::date LOOP
  SELECT max(id) INTO reopened FROM public.attendance_closeout_events WHERE action='reopen' AND through_date=day;
  SELECT e.* INTO event_row FROM public.attendance_closeout_events e
   WHERE e.action='close' AND day=ANY(e.affected_dates) AND e.id>coalesce(reopened,0) ORDER BY e.id DESC LIMIT 1;
  closed:=private.dashboard146_is_closed(day);
  dates:=dates||jsonb_build_array(jsonb_build_object('service_date',day,'status',CASE WHEN event_row.id IS NOT NULL AND closed THEN 'finalized'
    WHEN closed THEN 'closed_without_snapshot' WHEN reopened IS NOT NULL THEN 'reopened' ELSE 'open' END,'close_event_id',event_row.id,'closed_at',event_row.happened_at));
  IF event_row.id IS NULL OR NOT closed THEN CONTINUE; END IF;
  normalized:=cache->event_row.id::text;
  IF normalized IS NULL THEN
   normalized:=coalesce(event_row.snapshot->'monthly_report',private.dashboard147_normalize_snapshot(event_row.snapshot,false));
   cache:=cache||jsonb_build_object(event_row.id::text,normalized);
  END IF;
  stamp:=jsonb_build_object('close_event_id',event_row.id,'closed_at',event_row.happened_at,'legacy_snapshot',NOT(event_row.snapshot ? 'monthly_report'));
  SELECT coalesce(jsonb_agg(value||stamp),'[]') INTO rows_for_date FROM jsonb_array_elements(normalized->'deliveries') WHERE value->>'service_date'=day::text;
  deliveries:=deliveries||rows_for_date;
  SELECT coalesce(jsonb_agg(value||stamp),'[]') INTO rows_for_date FROM jsonb_array_elements(normalized->'standby') WHERE value->>'service_date'=day::text;
  shifts:=shifts||rows_for_date;
  SELECT coalesce(jsonb_agg(value||stamp),'[]') INTO rows_for_date FROM jsonb_array_elements(normalized->'special_work') WHERE value->>'service_date'=day::text;
  work_rows:=work_rows||rows_for_date;
  SELECT coalesce(jsonb_agg(value||stamp),'[]') INTO rows_for_date FROM jsonb_array_elements(normalized->'attendance_records') WHERE value->>'service_date'=day::text;
  attendance_rows:=attendance_rows||rows_for_date;
  SELECT coalesce(jsonb_agg(value||stamp||jsonb_build_object('finalized',true)),'[]') INTO rows_for_date FROM jsonb_array_elements(event_row.snapshot->'runs') WHERE value->>'service_date'=day::text;
  original_runs:=original_runs||rows_for_date;
 END LOOP;
 RETURN jsonb_build_object('version',147,'month',p_month,'deliveries',deliveries,'standby',shifts,'special_work',work_rows,
  'attendance_records',attendance_rows,'original_runs',original_runs,'dates',dates);
END $function$

CREATE OR REPLACE FUNCTION private.dashboard147_normalize_snapshot(p_snapshot jsonb, p_enrich boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
<<normalize>>
DECLARE
 r jsonb; o jsonb; w jsonb; x jsonb; item jsonb;
 delivery jsonb := '[]'; work_rows jsonb := '[]'; shift_rows jsonb := '[]'; attendance_rows jsonb := '[]';
 route_id bigint; vehicle_id bigint; driver_id uuid; route_code text; zone text; plate text; rental boolean;
BEGIN
 FOR r IN SELECT value FROM jsonb_array_elements(coalesce(p_snapshot->'runs','[]')) LOOP
  IF r->>'status' IN ('cancelled','void') THEN CONTINUE; END IF;
  SELECT value INTO o FROM jsonb_array_elements(coalesce(p_snapshot->'observations','[]')) WHERE value->>'run_id'=r->>'id' LIMIT 1;
  SELECT value INTO w FROM jsonb_array_elements(coalesce(p_snapshot->'special_work','[]'))
   WHERE value->>'run_id'=r->>'id' AND value->>'kind'='breakdown_replacement' AND value->>'review_status'<>'rejected' LIMIT 1;
  route_id:=coalesce((o->>'actual_route_id')::bigint,(r->>'route_id')::bigint);
  vehicle_id:=coalesce((w->>'vehicle_id')::bigint,(o->>'actual_vehicle_id')::bigint,(r->>'vehicle_id')::bigint);
  driver_id:=coalesce((w->>'driver_id')::uuid,(r->>'driver_id')::uuid);
  route_code:=CASE WHEN route_id=(r->>'route_id')::bigint THEN r->>'route_code_snapshot' END;
  zone:=CASE WHEN route_id=(r->>'route_id')::bigint THEN r->>'temperature_zone_snapshot' END;
  rental:=CASE WHEN vehicle_id=(r->>'vehicle_id')::bigint AND driver_id=(r->>'driver_id')::uuid THEN (r->>'is_rental')::boolean END;
  plate:=NULL;
  IF p_enrich THEN
   SELECT coalesce(normalize.route_code,t.route_code),coalesce(normalize.zone,t.temperature_zone) INTO route_code,zone FROM public.routes t WHERE t.id=route_id;
   SELECT v.plate_number INTO plate FROM public.vehicles v WHERE v.id=vehicle_id;
   IF vehicle_id IS DISTINCT FROM (r->>'vehicle_id')::bigint OR driver_id IS DISTINCT FROM (r->>'driver_id')::uuid THEN
    rental:=private.dashboard144_rental((r->>'service_date')::date,driver_id,vehicle_id);
   END IF;
  END IF;
  item:=r||jsonb_build_object('id','run:'||(r->>'id'),'source_type','run','run_id',r->'id','extra_trip_id',NULL,
   'driver_id',driver_id,'vehicle_id',vehicle_id,'route_id',route_id,'route_code_snapshot',route_code,
   'route_temperature_zone',zone,'temperature_zone_snapshot',zone,'plate_snapshot',plate,'is_rental',rental,
   'driver_notes',coalesce(o->>'actual_note',r->>'dispatcher_notes',r->>'driver_notes',r->>'notes',''),
   'replacement_work_id',w->'id','original_driver_id',r->'driver_id','finalized',true);
  delivery:=delivery||jsonb_build_array(item);
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(p_snapshot->'extra_trips','[]')) WHERE value->>'status'='active' LOOP
  route_code:=NULL;zone:=NULL;plate:=NULL;
  IF p_enrich THEN
   SELECT t.route_code,t.temperature_zone INTO route_code,zone FROM public.routes t WHERE t.id=(x->>'actual_route_id')::bigint;
   SELECT v.plate_number INTO plate FROM public.vehicles v WHERE v.id=(x->>'actual_vehicle_id')::bigint;
  END IF;
  delivery:=delivery||jsonb_build_array(x||jsonb_build_object('id','extra:'||(x->>'id'),'source_type','extra','run_id',NULL,'extra_trip_id',x->'id',
   'route_id',x->'actual_route_id','vehicle_id',x->'actual_vehicle_id','route_code_snapshot',route_code,'route_temperature_zone',zone,
   'temperature_zone_snapshot',zone,'plate_snapshot',plate,'driver_notes',x->'actual_note','finalized',true));
 END LOOP;
 FOR w IN SELECT value FROM jsonb_array_elements(coalesce(p_snapshot->'special_work','[]')) WHERE value->>'review_status'<>'rejected' LOOP
  -- Linked work is retained for reconciliation; it never creates a second delivery.
  work_rows:=work_rows||jsonb_build_array(w||jsonb_build_object('finalized',true));
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(p_snapshot->'standby','[]')) WHERE value->>'review_status'<>'rejected' LOOP
  shift_rows:=shift_rows||jsonb_build_array(x||jsonb_build_object('finalized',true,'converted_to_support',EXISTS(
   SELECT 1 FROM jsonb_array_elements(work_rows) a WHERE a->>'standby_shift_id'=x->>'id' AND a->>'kind' IN ('attached_support','breakdown_replacement'))));
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(p_snapshot->'attendance_records','[]')) WHERE value->>'review_status'<>'rejected' LOOP
  attendance_rows:=attendance_rows||jsonb_build_array(x||jsonb_build_object('finalized',true));
 END LOOP;

 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(p_snapshot->'duty_entries','[]')) WHERE value->>'status'='active' LOOP
  SELECT value INTO r FROM jsonb_array_elements(delivery) WHERE value->>'run_id'=x->>'linked_run_id' LIMIT 1;
  work_rows:=work_rows||jsonb_build_array(x||jsonb_build_object('id','duty:'||(x->>'id'),'source_type','attendance_duty',
   'run_id',x->'linked_run_id','vehicle_id',r->'vehicle_id','plate_snapshot',r->'plate_snapshot','route_code_snapshot',r->'route_code_snapshot',
   'pay_basis','per_entry','finalized',true));
 END LOOP;
 RETURN jsonb_build_object('version',147,'deliveries',delivery,'special_work',work_rows,'standby',shift_rows,'attendance_records',attendance_rows);
END $function$

CREATE OR REPLACE FUNCTION private.dashboard148_add_problem(p_date date, p_driver uuid, p_category text, p_slot integer, p_source_revision integer, p_route bigint, p_vehicle bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE slots integer;x public.daily_attendance_extra_trips%ROWTYPE;
BEGIN
 IF EXISTS(SELECT 1 FROM public.attendance_duty_entries WHERE service_date=p_date AND driver_id=p_driver AND attendance_category=p_category AND attendance_slot_index=p_slot AND status='active') THEN RETURN '此欄位已有跟車／學習';END IF;
 IF EXISTS(SELECT 1 FROM public.v055_standby_shifts WHERE service_date=p_date AND driver_id=p_driver AND attendance_category=p_category AND attendance_slot_index=p_slot AND review_status<>'rejected') THEN RETURN '此欄位已有值班';END IF;
 IF p_date IS NULL OR p_category IS NULL OR p_category NOT IN ('日配','OC','鮮二','冷凍','低鮮') OR p_slot IS NULL OR p_slot NOT BETWEEN 1 AND 30
  OR p_source_revision IS NULL OR p_source_revision<0 THEN RETURN '出勤日期、類別、欄位或版本無效';END IF;
 IF private.dashboard146_is_closed(p_date) THEN RETURN '此日期已結案，請先由調度員填寫原因重新開啟';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_driver AND active AND role='driver') THEN RETURN '司機帳號未啟用';END IF;
 IF EXISTS(SELECT 1 FROM public.attendance_driver_days WHERE service_date=p_date AND driver_id=p_driver AND is_leave) THEN RETURN '此司機當日休假';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.routes WHERE id=p_route AND active) OR NOT EXISTS(SELECT 1 FROM public.vehicles WHERE id=p_vehicle AND active)
  THEN RETURN '路線或車輛已變更／停用，請重新送審';END IF;
 SELECT coalesce((SELECT slot_count FROM public.daily_attendance_slot_counts WHERE service_date=p_date AND category=p_category),public.dashboard_attendance_slot_base(p_category)) INTO slots;
 IF p_slot>slots THEN RETURN '此欄位已被移除，請重新整理';END IF;
 IF EXISTS(SELECT 1 FROM public.runs r WHERE service_date=p_date AND driver_id=p_driver AND attendance_category=p_category AND attendance_slot_index=p_slot
  AND (status<>'cancelled' OR EXISTS(SELECT 1 FROM public.daily_run_observations o WHERE o.run_id=r.id))) THEN RETURN '此欄位已有預排趟次，新增申請未套用';END IF;
 SELECT * INTO x FROM public.daily_attendance_extra_trips WHERE service_date=p_date AND driver_id=p_driver AND attendance_category=p_category AND attendance_slot_index=p_slot;
 IF x.status='active' OR coalesce(x.revision,0)<>p_source_revision THEN RETURN '此欄位的趟次已變更，請重新整理';END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION private.dashboard148_guard_driver_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NOT NULL AND NOT private.is_dispatcher() THEN
  IF TG_TABLE_NAME<>'runs' OR TG_OP<>'UPDATE' THEN
   RAISE EXCEPTION '司機新增、刪除或修改趟次須先送出申請，經調度員核准後生效' USING ERRCODE='42501';
  END IF;
  -- Legacy start/completion signals are not assignment edits and do not gate monthly reporting.
  IF (to_jsonb(NEW)-ARRAY['status','actual_start_time','actual_end_time']) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['status','actual_start_time','actual_end_time']) THEN
   RAISE EXCEPTION '司機修改趟次或備註須先送出申請，經調度員核准後生效' USING ERRCODE='42501';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.dashboard148_request_add(p_service_date date, p_category text, p_slot_index integer, p_route_id bigint, p_vehicle_id bigint, p_note text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q public.attendance_change_requests%ROWTYPE;problem text;x public.daily_attendance_extra_trips%ROWTYPE;
BEGIN
 PERFORM private.dashboard143_lock();
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND active AND role='driver')
 THEN RAISE EXCEPTION '只有司機可送出本人新增趟次申請' USING ERRCODE='42501';END IF;
 IF length(coalesce(p_note,''))>1000 THEN RAISE EXCEPTION '備註不可超過 1000 字';END IF;
 problem:=private.dashboard148_add_problem(p_service_date,auth.uid(),p_category,p_slot_index,p_expected_revision,p_route_id,p_vehicle_id);
 IF problem IS NOT NULL THEN RAISE EXCEPTION '%',problem;END IF;
 SELECT * INTO q FROM public.attendance_change_requests WHERE request_kind='add' AND status='pending' AND service_date=p_service_date
  AND driver_id=auth.uid() AND attendance_category=p_category AND attendance_slot_index=p_slot_index FOR UPDATE;
 IF FOUND THEN
  IF q.source_revision=p_expected_revision AND q.proposed_route_id=p_route_id AND q.proposed_vehicle_id=p_vehicle_id AND q.proposed_note=coalesce(p_note,'')
  THEN RETURN jsonb_build_object('id',q.id,'status',q.status,'revision',q.revision);END IF;
  RAISE EXCEPTION '此欄位已有待審核新增申請，請先等待調度員處理';
 END IF;
 SELECT * INTO x FROM public.daily_attendance_extra_trips WHERE service_date=p_service_date AND driver_id=auth.uid() AND attendance_category=p_category AND attendance_slot_index=p_slot_index;
 INSERT INTO public.attendance_change_requests(request_kind,service_date,driver_id,source_revision,base_record,proposed_route_id,proposed_vehicle_id,proposed_note,
 requested_by,attendance_category,attendance_slot_index)
 VALUES('add',p_service_date,auth.uid(),p_expected_revision,jsonb_build_object('status','empty','previous_extra_id',x.id),p_route_id,p_vehicle_id,coalesce(p_note,''),auth.uid(),p_category,p_slot_index)
 RETURNING * INTO q;
 RETURN jsonb_build_object('id',q.id,'status',q.status,'revision',q.revision);
END $function$

CREATE OR REPLACE FUNCTION private.dashboard1491_stamp_supplement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT coalesce(private.can_manage_finance(),false) THEN RAISE EXCEPTION '僅 Brian 可設定值班／租車'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(1491,1);
 NEW.created_by:=auth.uid(); NEW.created_at:=clock_timestamp(); NEW.reason:=btrim(NEW.reason);
