CREATE OR REPLACE FUNCTION private.v05512_require_correct_replacement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.kind='breakdown_replacement' and new.review_status='confirmed'
     and old.review_status is distinct from new.review_status then
    if not exists(
      select 1 from public.trip_executions e
      where e.run_id=new.run_id and e.review_status='confirmed'
        and e.driver_id=new.driver_id and e.vehicle_id=new.vehicle_id
    ) then
      raise exception '主線實際趟次尚未確認，或接替司機／車輛歸屬未校正';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.v055_guard_new_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare conflict_id bigint; start_t time; end_t time; start_at timestamp; end_at timestamp;
begin
  if new.status='cancelled' then return new; end if;
  if tg_op='UPDATE' and row(new.service_date,new.route_id,new.driver_id,new.vehicle_id)
      is not distinct from row(old.service_date,old.route_id,old.driver_id,old.vehicle_id) then return new; end if;
  start_t:=new.planned_start_time;end_t:=new.planned_end_time;
  if start_t is null or end_t is null then return new; end if;
  start_at:=new.service_date+start_t;
  end_at:=new.service_date+end_t+case when end_t<start_t then interval '1 day' else interval '0 days' end;
  select w.id into conflict_id from public.v055_run_work w
    join public.runs parent on parent.id=w.run_id
    where w.review_status<>'rejected' and w.kind in ('follow_along','breakdown_replacement')
      and w.run_id is distinct from new.id
      and (w.driver_id=new.driver_id or (w.kind='breakdown_replacement' and w.vehicle_id=new.vehicle_id))
      and parent.planned_start_time is not null and parent.planned_end_time is not null
      and tsrange(parent.service_date+parent.planned_start_time,
          parent.service_date+parent.planned_end_time+
          case when parent.planned_end_time<parent.planned_start_time then interval '1 day' else interval '0 days' end,'[)')
          && tsrange(start_at,end_at,'[)') limit 1;
  if conflict_id is not null then raise exception '與已登記跟車／故障接替勤務 #% 時段衝突', conflict_id; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.v055_protect_parent_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists(select 1 from public.v055_run_work w where w.run_id=old.id and w.review_status<>'rejected') then
    if tg_op='DELETE' then raise exception '已有關聯特殊勤務，不能刪除原始趟次'; end if;
    if row(new.service_date,new.route_id,new.driver_id,new.vehicle_id,new.planned_start_time,new.planned_end_time)
       is distinct from row(old.service_date,old.route_id,old.driver_id,old.vehicle_id,old.planned_start_time,old.planned_end_time) then
      raise exception '已有關聯特殊勤務，不能直接改派原始趟次';
    end if;
    if new.status='cancelled' and old.status is distinct from 'cancelled' then
      raise exception '請先處理關聯特殊勤務，不能直接取消趟次';
    end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.v055_validate_run_work()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare src public.runs%rowtype; active_stage text; src_start time; src_end time;
    src_range tsrange; conflict_id bigint; lock_a bigint; lock_b bigint;
begin
  if not private.is_dispatcher() then raise exception '只有主管可以登記支援、接替或跟車'; end if;
  if tg_op='UPDATE' then
    if row(new.run_id,new.service_date,new.kind,new.driver_id,new.vehicle_id,new.standby_shift_id,
           new.follow_stage_snapshot,new.replacement_payee,new.support_reference,new.note,new.recorded_by,new.created_at)
       is distinct from row(old.run_id,old.service_date,old.kind,old.driver_id,old.vehicle_id,old.standby_shift_id,
           old.follow_stage_snapshot,old.replacement_payee,old.support_reference,old.note,old.recorded_by,old.created_at) then
      raise exception '特殊勤務來源資料不可直接修改；請退回並新增';
    end if;
    if old.review_status <> 'pending' and new.review_status is distinct from old.review_status then
      raise exception '此勤務已審核，不可直接重複審核';
    end if;
    if new.review_status='confirmed' and old.review_status is distinct from new.review_status then
      if not exists (select 1 from public.trip_executions e join public.runs r on r.id=e.run_id
          where e.run_id=new.run_id and e.review_status='confirmed' and r.status='completed') then
        raise exception '原始配送趟次尚未完成且確認，不能核准此特殊勤務';
      end if;
      if new.standby_shift_id is not null and not exists(
        select 1 from public.v055_standby_shifts s where s.id=new.standby_shift_id and s.review_status<>'rejected') then
        raise exception '關聯值班已被退回，無法核准';
      end if;
    end if;
    if new.review_status is distinct from old.review_status then
      new.reviewed_by:=auth.uid();new.reviewed_at:=clock_timestamp();
    else
      new.reviewed_by:=old.reviewed_by;new.reviewed_at:=old.reviewed_at;
    end if;
    new.updated_at:=clock_timestamp();
    return new;
  end if;
  if new.review_status<>'pending' or new.reviewed_by is not null or new.reviewed_at is not null then
    raise exception '新特殊勤務必須先進入待審核狀態'; end if;
  new.recorded_by:=auth.uid();new.created_at:=clock_timestamp();
  select * into src from public.runs where id=new.run_id for share;
  if not found or src.status='cancelled' then raise exception '原始趟次不存在或已取消'; end if;
  new.service_date:=src.service_date;
  src_start:=src.planned_start_time;src_end:=src.planned_end_time;
  if src_start is null or src_end is null or src_start=src_end then
    raise exception '此趟次缺少有效的原始固定時段，請檢查歷史資料';
  end if;
  src_range:=tsrange(src.service_date+src_start,
    src.service_date+src_end+case when src_end<src_start then interval '1 day' else interval '0 days' end,'[)');
  if not exists (select 1 from public.profiles p where p.id=new.driver_id and p.role='driver' and p.active) then
    raise exception '請選擇有效司機';
  end if;
  if new.kind='attached_support' then
    if new.driver_id<>src.driver_id or new.vehicle_id is distinct from src.vehicle_id then
      raise exception '附屬支援必須使用主線的同一位司機與車輛';
    end if;
    new.follow_stage_snapshot:=null;new.replacement_payee:=null;
    new.support_reference:=btrim(new.support_reference);
  elsif new.kind='breakdown_replacement' then
    if new.driver_id=src.driver_id or new.vehicle_id is null or new.vehicle_id=src.vehicle_id then
      raise exception '故障接替必須改派其他司機與其他車輛';
    end if;
    if new.replacement_payee not in ('replacement_only','both') or new.replacement_payee is null then
      raise exception '故障接替須選擇趟次歸屬（預設只計接替司機）';
    end if;
    new.follow_stage_snapshot:=null;new.support_reference:=null;
  elsif new.kind='follow_along' then
    if new.driver_id=src.driver_id or new.vehicle_id is distinct from src.vehicle_id then
      raise exception '跟車司機須不同於主線司機，並搭乘主線車輛';
    end if;
    select s.stage into active_stage from public.v055_driver_stages s
      where s.driver_id=new.driver_id and s.effective_from<=src.service_date
      order by s.effective_from desc limit 1;
    if active_stage is null then raise exception '請先設定跟車司機於配送當日的訓練／正式任職階段'; end if;
    new.follow_stage_snapshot:=active_stage;new.replacement_payee:=null;new.support_reference:=null;
    if new.standby_shift_id is not null then raise exception '跟車不可關聯值班班段'; end if;
  end if;
  -- If the driver has an overlapping standby shift, it must be explicitly
  -- associated. This avoids paying both standby and support for that shift.
  if new.kind in ('attached_support','breakdown_replacement')
     and new.standby_shift_id is null and exists(
        select 1 from public.v055_standby_shifts s
        where s.driver_id=new.driver_id and s.review_status<>'rejected' and s.start_time is not null and s.end_time is not null
          and tsrange(s.service_date+s.start_time,
              s.service_date+s.end_time+case when s.end_time<s.start_time then interval '1 day' else interval '0 days' end,'[)') && src_range)
  then raise exception '此司機有重疊值班班段，請明確選擇該班段以轉換支援'; end if;
  if new.standby_shift_id is not null then
    if not exists(select 1 from public.v055_standby_shifts s
      where s.id=new.standby_shift_id and s.driver_id=new.driver_id and s.start_time is not null and s.end_time is not null
        and s.review_status<>'rejected'
        and tsrange(s.service_date+s.start_time,
             s.service_date+s.end_time+case when s.end_time<s.start_time then interval '1 day' else interval '0 days' end,'[)') && src_range)
    then raise exception '關聯值班班段必須屬於同一司機並與此路線時段重疊'; end if;
  end if;
  -- A follow passenger or replacement driver cannot simultaneously drive another
  -- independent route. Attached support is explicitly nested in its parent.
  if new.kind in ('breakdown_replacement','follow_along') then
    lock_a:=pg_catalog.hashtextextended('dispatch-driver-'||new.driver_id::text,0);
    lock_b:=pg_catalog.hashtextextended('dispatch-vehicle-'||new.vehicle_id::text,0);
    perform pg_catalog.pg_advisory_xact_lock(least(lock_a,lock_b));
    if lock_a<>lock_b then perform pg_catalog.pg_advisory_xact_lock(greatest(lock_a,lock_b)); end if;
    select q.id into conflict_id from public.runs q
      join public.routes r on r.id=q.route_id
      where q.id<>src.id and q.driver_id=new.driver_id and q.status<>'cancelled'
        and coalesce(q.planned_start_time,r.default_start_time) is not null
        and coalesce(q.planned_end_time,r.default_end_time) is not null
        and tsrange(q.service_date+coalesce(q.planned_start_time,r.default_start_time),
          q.service_date+coalesce(q.planned_end_time,r.default_end_time)+
            case when coalesce(q.planned_end_time,r.default_end_time)<coalesce(q.planned_start_time,r.default_start_time)
            then interval '1 day' else interval '0 days' end,'[)') && src_range
      limit 1;
    if conflict_id is not null then raise exception '此司機已有衝突的獨立趟次 #%',conflict_id; end if;
    -- A separate replacement cannot use a vehicle on a different scheduled route.
    if new.kind='breakdown_replacement' then
      select q.id into conflict_id from public.runs q join public.routes r on r.id=q.route_id
        where q.id<>src.id and q.vehicle_id=new.vehicle_id and q.status<>'cancelled'
          and coalesce(q.planned_start_time,r.default_start_time) is not null
          and coalesce(q.planned_end_time,r.default_end_time) is not null
          and tsrange(q.service_date+coalesce(q.planned_start_time,r.default_start_time),
            q.service_date+coalesce(q.planned_end_time,r.default_end_time)+
            case when coalesce(q.planned_end_time,r.default_end_time)<coalesce(q.planned_start_time,r.default_start_time)
            then interval '1 day' else interval '0 days' end,'[)') && src_range limit 1;
      if conflict_id is not null then raise exception '接替車輛已有衝突趟次 #%',conflict_id; end if;
    end if;
    select w.id into conflict_id from public.v055_run_work w
      join public.runs q on q.id=w.run_id
      where w.review_status<>'rejected'
        and w.kind in ('follow_along','breakdown_replacement')
        and (w.driver_id=new.driver_id or (new.kind='breakdown_replacement' and w.kind='breakdown_replacement' and w.vehicle_id=new.vehicle_id))
        and tsrange(q.service_date+q.planned_start_time,
          q.service_date+q.planned_end_time+case when q.planned_end_time<q.planned_start_time then interval '1 day' else interval '0 days' end,'[)') && src_range
      limit 1;
    if conflict_id is not null then raise exception '司機或車輛已有重疊的跟車／接替勤務 #%',conflict_id; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.v055_validate_shift()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE conflict_id bigint;lim integer;
BEGIN
 PERFORM private.dashboard143_require_dispatcher();
 PERFORM private.dashboard143_open_day(NEW.service_date);
 IF TG_OP='UPDATE' THEN
  IF (NEW.id,NEW.service_date,NEW.driver_id,NEW.recorded_by,NEW.created_at,NEW.attendance_category,NEW.attendance_slot_index)
   IS DISTINCT FROM (OLD.id,OLD.service_date,OLD.driver_id,OLD.recorded_by,OLD.created_at,OLD.attendance_category,OLD.attendance_slot_index)
  THEN RAISE EXCEPTION '不可變更值班紀錄的司機、日期、欄位或建立資訊';END IF;
  IF OLD.review_status='rejected' THEN RAISE EXCEPTION '已撤銷值班不可重新啟用，請新增勤務';END IF;
  IF (NEW.start_time,NEW.end_time,NEW.review_status='rejected') IS DISTINCT FROM (OLD.start_time,OLD.end_time,OLD.review_status='rejected')
   AND EXISTS(SELECT 1 FROM public.v055_run_work WHERE standby_shift_id=OLD.id AND review_status<>'rejected')
  THEN RAISE EXCEPTION '此值班已有特殊勤務關聯，請先處理關聯紀錄再調整時段或撤銷';END IF;
  NEW.revision:=OLD.revision+1;
  IF NEW.review_status IS DISTINCT FROM OLD.review_status THEN NEW.reviewed_by:=auth.uid();NEW.reviewed_at:=clock_timestamp();
  ELSE NEW.reviewed_by:=OLD.reviewed_by;NEW.reviewed_at:=OLD.reviewed_at;END IF;
 ELSE
  IF NEW.review_status<>'pending' OR NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL
  THEN RAISE EXCEPTION '新值班紀錄狀態不正確';END IF;
  NEW.recorded_by:=auth.uid();NEW.created_at:=clock_timestamp();NEW.revision:=1;
 END IF;
 NEW.updated_at:=clock_timestamp();
 IF length(NEW.note)>1000 THEN RAISE EXCEPTION '備註不可超過 1000 字';END IF;
 IF NEW.review_status='rejected' THEN RETURN NEW;END IF;
 PERFORM private.dashboard143_require_driver(NEW.driver_id);
 IF EXISTS(SELECT 1 FROM public.attendance_driver_days WHERE service_date=NEW.service_date AND driver_id=NEW.driver_id AND is_leave)
 THEN RAISE EXCEPTION '此司機當日休假';END IF;
 IF NEW.attendance_category IS NOT NULL THEN
  SELECT coalesce((SELECT slot_count FROM public.daily_attendance_slot_counts WHERE service_date=NEW.service_date AND category=NEW.attendance_category),public.dashboard_attendance_slot_base(NEW.attendance_category)) INTO lim;
  IF NEW.attendance_slot_index>lim THEN RAISE EXCEPTION '出勤欄位已變更，請重新整理';END IF;
  IF EXISTS(SELECT 1 FROM public.runs WHERE service_date=NEW.service_date AND driver_id=NEW.driver_id
    AND attendance_category=NEW.attendance_category AND attendance_slot_index=NEW.attendance_slot_index
    AND (status<>'cancelled' OR EXISTS(SELECT 1 FROM public.daily_run_observations WHERE run_id=public.runs.id)))
   OR EXISTS(SELECT 1 FROM public.daily_attendance_extra_trips WHERE service_date=NEW.service_date AND driver_id=NEW.driver_id
    AND attendance_category=NEW.attendance_category AND attendance_slot_index=NEW.attendance_slot_index AND status='active')
  THEN RAISE EXCEPTION '此欄位已有配送紀錄';END IF;
 END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('v055-shift-'||NEW.driver_id::text,0));
 IF NEW.start_time IS NULL AND NEW.end_time IS NULL THEN RETURN NEW;END IF;
 SELECT id INTO conflict_id FROM public.v055_standby_shifts s WHERE s.start_time IS NOT NULL AND s.end_time IS NOT NULL AND s.id<>NEW.id AND s.driver_id=NEW.driver_id AND s.review_status<>'rejected'
  AND tsrange(s.service_date+s.start_time,s.service_date+s.end_time+CASE WHEN s.end_time<s.start_time THEN interval '1 day' ELSE interval '0 day' END,'[)')
   && tsrange(NEW.service_date+NEW.start_time,NEW.service_date+NEW.end_time+CASE WHEN NEW.end_time<NEW.start_time THEN interval '1 day' ELSE interval '0 day' END,'[)') LIMIT 1;
 IF conflict_id IS NOT NULL THEN RAISE EXCEPTION '司機值班時段重疊：班段 #%',conflict_id;END IF;
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION private.v055_validate_stage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_dispatcher() then raise exception '只有主管可以登記司機任職階段'; end if;
  if tg_op = 'UPDATE' then raise exception '任職階段紀錄不可修改，請新增新的生效日'; end if;
  new.created_by:=auth.uid();new.created_at:=clock_timestamp();
  if not exists (select 1 from public.profiles p where p.id=new.driver_id and p.role='driver') then
    raise exception '階段紀錄只能套用於司機';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.validate_route_and_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_dispatcher() then raise exception '只有主管可以修改配送路線'; end if;
  new.route_code := btrim(new.route_code);
  if tg_op='UPDATE' and new.active=false and old.active is distinct from new.active
      and row(new.route_code,new.route_name,new.temperature_zone,new.default_start_time,new.default_end_time)
         is not distinct from
          row(old.route_code,old.route_name,old.temperature_zone,old.default_start_time,old.default_end_time) then
    return new; -- Allow the supervisor to deactivate a legacy/incomplete route.
  end if;
  new.route_name := nullif(btrim(coalesce(new.route_name,'')),'');
  new.temperature_zone := nullif(btrim(coalesce(new.temperature_zone,'')),'');
  if new.route_code = '' then raise exception '必須填寫路線編號'; end if;
  if new.temperature_zone is null then raise exception '必須設定溫層'; end if;
  if new.default_start_time is null or new.default_end_time is null
      or new.default_start_time = new.default_end_time then
    raise exception '必須設定不同的固定開始與結束時間';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.dashboard_add_payroll_rate(p_driver_id uuid, p_component text, p_route_id bigint, p_amount numeric, p_effective_from date, p_effective_to date, p_explanation text, p_supersedes_id bigint DEFAULT NULL::bigint, p_expected jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old_row public.payroll_rules; result_row public.payroll_rules; end_date date:=p_effective_to;
BEGIN
 IF NOT coalesce(private.can_manage_finance(),false) THEN RAISE EXCEPTION '僅 Brian 可設定計薪'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(149,1);
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_driver_id AND role='driver' AND active) THEN RAISE EXCEPTION '請選擇啟用中的司機'; END IF;
 IF p_component IS NULL OR p_component NOT IN ('fixed_monthly','per_run') THEN RAISE EXCEPTION '計薪項目無效'; END IF;
 IF (p_component='fixed_monthly' AND p_route_id IS NOT NULL) OR (p_component='per_run' AND NOT EXISTS(SELECT 1 FROM public.routes WHERE id=p_route_id AND active)) THEN RAISE EXCEPTION '請選擇正確的計薪路線'; END IF;
 IF p_amount IS NULL OR p_amount<0 OR p_amount>10000000 OR p_amount<>trunc(p_amount) THEN RAISE EXCEPTION '費率請輸入 0 至 10,000,000 的整數'; END IF;
 IF p_effective_from IS NULL OR p_effective_from<'1900-01-01' OR p_effective_from>'9998-12-31' OR (end_date IS NOT NULL AND (end_date<p_effective_from OR end_date>'9998-12-31')) THEN RAISE EXCEPTION '費率有效日期不正確'; END IF;
 IF coalesce(length(btrim(p_explanation)),0)=0 OR length(p_explanation)>2000 THEN RAISE EXCEPTION '請填寫 1 至 2000 字的費率依據'; END IF;
 IF p_supersedes_id IS NOT NULL THEN
  SELECT * INTO old_row FROM public.payroll_rules WHERE id=p_supersedes_id FOR UPDATE;
  IF NOT FOUND OR p_expected IS DISTINCT FROM to_jsonb(old_row) THEN RAISE EXCEPTION '費率已變更，請重新整理後再操作'; END IF;
  IF NOT old_row.active OR old_row.driver_id<>p_driver_id OR old_row.component<>p_component OR old_row.route_id IS DISTINCT FROM p_route_id THEN RAISE EXCEPTION '新費率必須延續相同司機及計薪項目'; END IF;
  IF p_effective_from<=old_row.effective_from OR (old_row.effective_to IS NOT NULL AND p_effective_from>old_row.effective_to) THEN RAISE EXCEPTION '新費率須在原期間內、原生效日之後開始'; END IF;
  end_date:=coalesce(end_date,old_row.effective_to);
  UPDATE public.payroll_rules SET effective_to=p_effective_from-1 WHERE id=old_row.id;
 ELSIF p_expected IS NOT NULL THEN RAISE EXCEPTION '新增費率不可指定舊版本'; END IF;
 INSERT INTO public.payroll_rules(driver_id,component,route_id,amount,effective_from,effective_to,explanation,active,created_by)
 VALUES(p_driver_id,p_component,p_route_id,p_amount,p_effective_from,end_date,btrim(p_explanation),true,auth.uid()) RETURNING * INTO result_row;
 RETURN to_jsonb(result_row);
END $function$

CREATE OR REPLACE FUNCTION public.dashboard_apply_day_template(p_driver_id uuid, p_template_revision integer, p_dates date[], p_expected_days jsonb, p_overwrite boolean, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.driver_day_templates%ROWTYPE;batch public.attendance_template_batches%ROWTYPE;
 d date;s public.attendance_driver_days%ROWTYPE;clean jsonb;x jsonb;r public.runs%ROWTYPE;
 request jsonb;result jsonb;applied jsonb:='[]';skipped jsonb:='[]';why text;cat text;lim integer;need integer;
BEGIN
 PERFORM private.dashboard143_lock();PERFORM private.dashboard143_require_dispatcher();PERFORM private.dashboard143_require_driver(p_driver_id);
 IF p_request_id IS NULL OR p_template_revision IS NULL OR p_dates IS NULL OR cardinality(p_dates)<1
  OR cardinality(p_dates)>366 OR array_position(p_dates,NULL) IS NOT NULL OR p_overwrite IS NULL
  OR p_expected_days IS NULL OR jsonb_typeof(p_expected_days)<>'object'
 THEN RAISE EXCEPTION '請選取日期（單次最多 366 天）並重新載入預覽';END IF;
 request:=jsonb_build_object('driver',p_driver_id,'revision',p_template_revision,'dates',(SELECT jsonb_agg(z.selected_date ORDER BY z.selected_date) FROM (SELECT DISTINCT unnest(p_dates) selected_date) z),
  'expected',p_expected_days,'overwrite',p_overwrite);
 SELECT * INTO batch FROM public.attendance_template_batches WHERE request_id=p_request_id;
 IF FOUND THEN
  IF batch.actor_id<>auth.uid() OR batch.request_payload<>request THEN RAISE EXCEPTION '此請求識別碼已用於另一筆操作';END IF;
  RETURN batch.result; -- retry after a lost response cannot duplicate runs
 END IF;
 SELECT * INTO t FROM public.driver_day_templates WHERE driver_id=p_driver_id FOR UPDATE;
 IF NOT FOUND OR t.revision<>p_template_revision THEN RAISE EXCEPTION '範本已被更新，請重新載入後再套用';END IF;
 clean:=private.dashboard143_normalize_rows(t.rows);
 FOR d IN SELECT DISTINCT unnest(p_dates) ORDER BY 1 LOOP
  SELECT * INTO s FROM public.attendance_driver_days WHERE service_date=d AND driver_id=p_driver_id FOR UPDATE;
  why:=NULL;
  IF EXISTS(SELECT 1 FROM public.daily_attendance_closeouts WHERE service_date=d AND closed_at IS NOT NULL) THEN why:='已結案';
  ELSIF coalesce(s.is_leave,false) THEN why:='休假';
  ELSIF EXISTS(SELECT 1 FROM public.attendance_duty_entries WHERE service_date=d AND driver_id=p_driver_id AND status='active') THEN why:='保留跟車／學習，請從出勤表調整';
  ELSIF EXISTS(SELECT 1 FROM public.v055_standby_shifts WHERE service_date=d AND driver_id=p_driver_id AND review_status<>'rejected') THEN why:='保留值班，請從出勤表調整';
  ELSIF NOT p_overwrite AND (coalesce(s.has_plan_exception,false) OR (s.template_revision IS NULL AND private.dashboard143_has_runs(d,p_driver_id))) THEN why:='保留單日調整';
  ELSIF EXISTS(SELECT 1 FROM public.runs WHERE service_date=d AND driver_id=p_driver_id AND status::text NOT IN ('assigned','cancelled'))
   OR EXISTS(SELECT 1 FROM public.trip_executions e LEFT JOIN public.runs er ON er.id=e.run_id
    WHERE (e.service_date=d AND e.driver_id=p_driver_id) OR (er.service_date=d AND er.driver_id=p_driver_id)) THEN why:='已有實際執行或送審紀錄';
  ELSIF private.dashboard143_has_special_links(d,p_driver_id) THEN why:='保留特殊勤務關聯的預排';
  ELSIF EXISTS(SELECT 1 FROM public.runs WHERE service_date=d AND driver_id=p_driver_id AND status::text<>'cancelled' AND attendance_category IS NULL) THEN why:='有未分類預排，請先指定欄位';
  ELSIF EXISTS(SELECT 1 FROM public.daily_attendance_extra_trips WHERE service_date=d AND driver_id=p_driver_id AND status='active') THEN why:='保留臨時實際趟次，請先人工確認';
  END IF;
  IF why IS NOT NULL THEN skipped:=skipped||jsonb_build_array(jsonb_build_object('date',d,'reason',why));CONTINUE;END IF;
  IF coalesce(p_expected_days->>d::text,'')!~'^[0-9]+$' OR (p_expected_days->>d::text)::integer<>coalesce(s.revision,0)
  THEN RAISE EXCEPTION '日期 % 已被更新；本批未寫入，請重新載入日期後再試',d;END IF;
  PERFORM private.dashboard143_open_day(d);
  -- Preserve each existing run ID (and its observations). Cancelling first avoids
  -- false conflicts while replacing two routes whose order has changed.
  UPDATE public.runs SET status='cancelled' WHERE service_date=d AND driver_id=p_driver_id AND status::text='assigned';
  FOREACH cat IN ARRAY ARRAY['日配','OC','鮮二','冷凍','低鮮'] LOOP
   SELECT coalesce(max((value->>'slot_index')::integer),0) INTO need FROM jsonb_array_elements(clean) WHERE value->>'category'=cat;
   SELECT coalesce((SELECT slot_count FROM public.daily_attendance_slot_counts WHERE service_date=d AND category=cat),public.dashboard_attendance_slot_base(cat)) INTO lim;
   IF need>lim THEN INSERT INTO public.daily_attendance_slot_counts(service_date,category,slot_count) VALUES(d,cat,need)
    ON CONFLICT(service_date,category) DO UPDATE SET slot_count=excluded.slot_count;END IF;
  END LOOP;
  FOR x IN SELECT value FROM jsonb_array_elements(clean) LOOP
   SELECT * INTO r FROM public.runs q WHERE q.service_date=d AND q.driver_id=p_driver_id
    AND q.attendance_category=x->>'category' AND q.attendance_slot_index=(x->>'slot_index')::integer
    ORDER BY EXISTS(SELECT 1 FROM public.daily_run_observations o WHERE o.run_id=q.id) DESC,q.id DESC LIMIT 1 FOR UPDATE;
   PERFORM private.dashboard143_check_conflict(d,p_driver_id,(x->>'vehicle_id')::bigint,(x->>'route_id')::bigint,r.id);
   IF r.id IS NULL THEN
    INSERT INTO public.runs(service_date,driver_id,route_id,vehicle_id,is_rental,status,attendance_category,attendance_slot_index)
    VALUES(d,p_driver_id,(x->>'route_id')::bigint,(x->>'vehicle_id')::bigint,(x->>'is_rental')::boolean,'assigned',x->>'category',(x->>'slot_index')::integer);
   ELSE
    UPDATE public.runs SET route_id=(x->>'route_id')::bigint,vehicle_id=(x->>'vehicle_id')::bigint,
     is_rental=(x->>'is_rental')::boolean,status='assigned' WHERE id=r.id;
   END IF;
  END LOOP;
  INSERT INTO public.attendance_driver_days(service_date,driver_id,revision,has_plan_exception,template_revision,applied_rows,updated_by)
   VALUES(d,p_driver_id,1,false,t.revision,clean,auth.uid()) ON CONFLICT(service_date,driver_id) DO UPDATE SET
   revision=public.attendance_driver_days.revision+1,has_plan_exception=false,template_revision=t.revision,applied_rows=clean,updated_at=now(),updated_by=auth.uid();
  applied:=applied||jsonb_build_array(d);
 END LOOP;
 result:=jsonb_build_object('request_id',p_request_id,'applied_dates',applied,'skipped',skipped,'template_revision',t.revision);
 INSERT INTO public.attendance_template_batches(request_id,driver_id,actor_id,request_payload,result) VALUES(p_request_id,p_driver_id,auth.uid(),request,result);
 RETURN result;
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_edit_run_direct(p_run_id bigint, p_route_id bigint, p_vehicle_id bigint, p_note text, p_expected_run_revision integer, p_expected_observation_revision integer DEFAULT 0, p_cancel boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.runs%ROWTYPE;o public.daily_run_observations%ROWTYPE;n integer;
BEGIN
 PERFORM private.dashboard143_lock();PERFORM private.dashboard143_require_dispatcher();
 SELECT * INTO r FROM public.runs WHERE id=p_run_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION '找不到配送趟次';END IF;
 PERFORM private.dashboard143_open_day(r.service_date);
 IF p_expected_run_revision IS NULL OR r.dashboard_schedule_revision<>p_expected_run_revision
 THEN RAISE EXCEPTION '趟次已被更新，請重新整理';END IF;
 IF EXISTS(SELECT 1 FROM public.attendance_driver_days WHERE service_date=r.service_date AND driver_id=r.driver_id AND is_leave)
 THEN RAISE EXCEPTION '此司機當日休假';END IF;
 IF r.status NOT IN ('assigned','in_progress','completed') THEN RAISE EXCEPTION '已取消趟次不可修改';END IF;
 IF coalesce(p_cancel,false) AND (r.status<>'assigned' OR EXISTS(SELECT 1 FROM public.trip_executions WHERE run_id=r.id))
 THEN RAISE EXCEPTION '只能取消尚未開始且沒有執行紀錄的趟次';END IF;
 IF NOT coalesce(p_cancel,false) AND (
  NOT EXISTS(SELECT 1 FROM public.routes WHERE id=p_route_id AND (active OR id=r.route_id))
  OR NOT EXISTS(SELECT 1 FROM public.vehicles WHERE id=p_vehicle_id AND (active OR id=r.vehicle_id)))
 THEN RAISE EXCEPTION '請選擇有效的路線與車輛';END IF;
 IF length(coalesce(p_note,''))>1000 THEN RAISE EXCEPTION '備註不可超過 1000 字';END IF;
 SELECT * INTO o FROM public.daily_run_observations WHERE run_id=r.id FOR UPDATE;
 IF p_expected_observation_revision IS NULL OR coalesce(o.revision,0)<>p_expected_observation_revision
 THEN RAISE EXCEPTION '出勤資料已被更新，請重新整理';END IF;
 PERFORM pg_catalog.set_config('app.dashboard146_run',auth.uid()::text||':'||r.id::text,true);
 IF o.id IS NOT NULL THEN DELETE FROM public.daily_run_observations WHERE id=o.id;END IF;
 IF coalesce(p_cancel,false) THEN
  UPDATE public.runs SET status='cancelled',dispatcher_notes=nullif(btrim(coalesce(p_note,'')),'')
  WHERE id=r.id RETURNING dashboard_schedule_revision INTO n;
 ELSE
  UPDATE public.runs SET route_id=p_route_id,vehicle_id=p_vehicle_id,dispatcher_notes=nullif(btrim(coalesce(p_note,'')),'')
  WHERE id=r.id RETURNING dashboard_schedule_revision INTO n;
  -- Keep actual execution identity, review status and completion notes. Ordinary
  -- route/vehicle corrections update the same execution; never add a second trip.
  UPDATE public.trip_executions e SET route_id=s.route_id,vehicle_id=s.vehicle_id,
   route_temperature_zone=s.temperature_zone_snapshot,route_start_time=s.planned_start_time,
   route_end_time=s.planned_end_time,route_code_snapshot=s.route_code_snapshot,
   updated_at=clock_timestamp()
  FROM public.runs s WHERE s.id=r.id AND e.run_id=s.id AND e.driver_id=s.driver_id
   AND ROW(e.route_id,e.vehicle_id,e.route_temperature_zone,e.route_start_time,e.route_end_time,e.route_code_snapshot)
    IS DISTINCT FROM ROW(s.route_id,s.vehicle_id,s.temperature_zone_snapshot,s.planned_start_time,s.planned_end_time,s.route_code_snapshot);
 END IF;
 PERFORM pg_catalog.set_config('app.dashboard146_run','',true);
 RETURN jsonb_build_object('run_id',r.id,'revision',n,'cancelled',coalesce(p_cancel,false));
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_end_payroll_rate(p_rule_id bigint, p_expected jsonb, p_effective_to date, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old_row public.payroll_rules; result_row public.payroll_rules;
BEGIN
 IF NOT coalesce(private.can_manage_finance(),false) THEN RAISE EXCEPTION '僅 Brian 可設定計薪'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(149,1);
 IF coalesce(length(btrim(p_reason)),0)=0 OR length(p_reason)>2000 THEN RAISE EXCEPTION '請填寫 1 至 2000 字的變更原因'; END IF;
 SELECT * INTO old_row FROM public.payroll_rules WHERE id=p_rule_id FOR UPDATE;
 IF NOT FOUND OR p_expected IS DISTINCT FROM to_jsonb(old_row) THEN RAISE EXCEPTION '費率已變更，請重新整理後再操作'; END IF;
 IF NOT old_row.active THEN RAISE EXCEPTION '費率已停用'; END IF;
 IF p_effective_to IS NOT NULL AND (p_effective_to<old_row.effective_from OR p_effective_to>'9998-12-31' OR (old_row.effective_to IS NOT NULL AND p_effective_to>old_row.effective_to)) THEN RAISE EXCEPTION '結束日須在原有效期間內'; END IF;
 UPDATE public.payroll_rules SET active=p_effective_to IS NOT NULL,effective_to=coalesce(p_effective_to,effective_to),
  explanation=left(explanation,2000)||E'\n'||CASE WHEN p_effective_to IS NULL THEN '停用：' ELSE '結束期間：' END||btrim(p_reason)
 WHERE id=p_rule_id RETURNING * INTO result_row;
 RETURN to_jsonb(result_row);
END $function$

CREATE OR REPLACE FUNCTION public.dashboard_get_attendance_day_state(p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb; closed boolean;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND active)
 THEN RAISE EXCEPTION '請先登入' USING ERRCODE='42501';END IF;
 IF p_date IS NULL THEN RAISE EXCEPTION '請指定日期';END IF;
 closed:=private.dashboard146_is_closed(p_date);
 SELECT to_jsonb(c) INTO result FROM public.daily_attendance_closeouts c WHERE service_date=p_date;
 result:=coalesce(result,jsonb_build_object('service_date',p_date));
 IF closed THEN
  result:=result||jsonb_build_object('closed_at',coalesce(
   (SELECT happened_at FROM public.attendance_closeout_events WHERE action='close' AND through_date>=p_date ORDER BY id DESC LIMIT 1),
   (SELECT closed_at FROM public.daily_attendance_closeouts WHERE service_date=p_date)));
 ELSE result:=result||jsonb_build_object('closed_at',NULL);END IF;
 RETURN result||jsonb_build_object('closed',closed);
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_get_calculated_payroll(p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE b jsonb;f jsonb;d record;x record;r jsonb;rate jsonb;parts jsonb;line jsonb;
 lines jsonb:='[]';issues jsonb:='[]';driver_issues jsonb;summaries jsonb:='[]';counts jsonb;
 amount numeric;subtotal numeric;valid boolean;code text;message text;label text;k text;date_text text;
BEGIN
 IF NOT coalesce(private.can_manage_finance(),false) THEN RAISE EXCEPTION '僅 Brian 可查看月度報表';END IF;
 -- Existing RPC validates month, enforces Brian-only RLS and reads 結案 snapshots.
 b:=public.dashboard_get_route_payroll(p_month);f:=b->'finalized';
 IF f->>'version'<>'147' OR f->>'month'<>p_month::text THEN RAISE EXCEPTION '結案月報資料版本不正確';END IF;
 FOREACH k IN ARRAY ARRAY['deliveries','standby','special_work','attendance_records'] LOOP
  IF jsonb_typeof(f->k)<>'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(f->k) q WHERE q->>'finalized' IS DISTINCT FROM 'true'
   OR q->>'id' IS NULL OR q->>'driver_id' IS NULL OR q->>'close_event_id' IS NULL
   OR (q->>'service_date')::date<p_month OR (q->>'service_date')::date>=(p_month+interval '1 month')::date
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(f->'dates') z WHERE z->>'status'='finalized' AND z->>'service_date'=q->>'service_date'))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(f->k) q GROUP BY q->>'id' HAVING count(*)>1)
  THEN RAISE EXCEPTION '結案對帳來源不一致';END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(f->'dates') WHERE value->>'status'<>'finalized' LOOP
  issues:=issues||jsonb_build_array(jsonb_build_object('code','date_unfinalized','driverId','','date',r->>'service_date','source','',
   'message',CASE WHEN r->>'status'='reopened' THEN '日期已重新開啟，未計入本次對帳' ELSE '日期尚未結案或缺少結案快照，未計入本次對帳' END));
 END LOOP;
 FOR d IN
  WITH ids AS (
   SELECT id::text id FROM public.profiles WHERE role='driver'
   UNION SELECT q->>'driver_id' FROM jsonb_array_elements((b->'adjustments')||(f->'deliveries')||(f->'standby')||(f->'special_work')||(f->'attendance_records')) q
   UNION SELECT o->>'driver_id' FROM jsonb_array_elements(f->'original_runs') o JOIN jsonb_array_elements(f->'special_work') w ON w->>'kind'='breakdown_replacement' AND w->>'run_id'=o->>'id'
   UNION SELECT o->>'original_driver_id' FROM jsonb_array_elements(f->'deliveries') o JOIN jsonb_array_elements(f->'special_work') w ON w->>'kind'='breakdown_replacement' AND w->>'run_id'=o->>'run_id'
  ) SELECT ids.id,coalesce(p.display_name,'未列於司機名冊') name FROM ids LEFT JOIN public.profiles p ON p.id::text=ids.id WHERE ids.id IS NOT NULL ORDER BY ids.id
 LOOP
  parts:='{"per_run":0,"rental":0,"adjustment":0}';driver_issues:='[]';
  FOR x IN
   SELECT 'per_run' kind,q item,q->>'id' source FROM jsonb_array_elements(f->'deliveries') q WHERE q->>'driver_id'=d.id
   UNION ALL SELECT 'rental',q,q->>'id' FROM jsonb_array_elements(f->'deliveries') q WHERE q->>'driver_id'=d.id AND q->>'is_rental'='true'
   UNION ALL SELECT 'adjustment',q,'adjustment:'||(q->>'id') FROM jsonb_array_elements(b->'adjustments') q WHERE q->>'driver_id'=d.id
  LOOP
   rate:=NULL;code:=NULL;message:=NULL;date_text:=x.item->>'service_date';
   label:='租車費用';
   IF x.kind='per_run' THEN
    SELECT q INTO rate FROM jsonb_array_elements(b->'route_rates') q WHERE q->>'route_id'=x.item->>'route_id';
    amount:=(rate->>'amount')::numeric;
    valid:=coalesce(amount>=0 AND amount=trunc(amount,2) AND abs(amount)*100<=9007199254740991 AND rate->>'region_id' IS NOT NULL
     AND nullif(x.item->>'route_temperature_zone','') IS NOT NULL AND rate->>'zone_name'=x.item->>'route_temperature_zone',false);
    IF NOT valid THEN code:='route_rate_missing';message:='路線管理費率未設定，或目前溫層與結案紀錄不符';END IF;
    line:=jsonb_build_object('routeId',x.item->'route_id','routeCode',coalesce(x.item->>'route_code_snapshot',''),'temperatureZone',coalesce(x.item->>'route_temperature_zone',''),
     'ruleId',CASE WHEN valid THEN 'route:'||(rate->>'region_id')||':'||(rate->>'zone_name') END,'rateUpdatedAt',rate->'updated_at',
     'status',CASE WHEN valid THEN '路線管理目前費率（試算）' ELSE '待設定' END);
   ELSIF x.kind='adjustment' THEN
    amount:=(x.item->>'amount')::numeric;
    valid:=coalesce(amount=trunc(amount,2) AND abs(amount)*100<=9007199254740991 AND date_text::date>=p_month AND date_text::date<(p_month+interval '1 month')::date,false);
    IF NOT valid THEN code:='adjustment_invalid';message:='調整金額或月份無效';END IF;
    line:=jsonb_build_object('ruleId',NULL,'status','月報人工調整');
   ELSE
    SELECT q INTO rate FROM jsonb_array_elements(b->'supplements') q WHERE q->>'component'=x.kind AND q->>'effective_from'<=date_text ORDER BY q->>'effective_from' DESC,(q->>'id')::bigint DESC LIMIT 1;
    amount:=(rate->>'amount')::numeric;
    valid:=coalesce(amount>=0 AND amount=trunc(amount,2) AND abs(amount)*100<=9007199254740991,false);
    IF NOT valid THEN code:=x.kind||'_rate_missing';message:=CASE WHEN x.kind='rental' THEN '租車費用尚未設定，扣款待確認' ELSE label||'尚未設定' END;END IF;
    IF x.kind='rental' THEN amount:=-amount;END IF;
    line:=jsonb_build_object('ruleId',rate->'id','status',CASE WHEN NOT valid THEN '待設定' WHEN x.kind='rental' THEN '自薪資扣除' ELSE '加入薪資' END);
   END IF;
   IF NOT valid THEN amount:=NULL;END IF;
   parts:=jsonb_set(parts,ARRAY[x.kind],coalesce(to_jsonb((parts->>x.kind)::numeric+amount),'null'::jsonb));
   lines:=lines||jsonb_build_array(line||jsonb_build_object('driverId',d.id,'date',date_text,'source',x.source,'kind',x.kind,'quantity',1,
    'amount',amount,'closeEventId',CASE WHEN x.kind='adjustment' THEN NULL ELSE x.item->'close_event_id' END));
   IF code IS NOT NULL THEN driver_issues:=driver_issues||jsonb_build_array(jsonb_build_object('code',code,'driverId',d.id,'date',date_text,'source',x.source,'message',message));END IF;
  END LOOP;
  FOR r IN SELECT q FROM jsonb_array_elements(f->'deliveries') q WHERE q->>'driver_id'=d.id AND (q->>'is_rental' IS NULL OR q->>'is_rental' NOT IN ('true','false')) LOOP
   parts:=jsonb_set(parts,'{rental}','null');
   driver_issues:=driver_issues||jsonb_build_array(jsonb_build_object('code','rental_unknown','driverId',d.id,'date',r->>'service_date','source',r->>'id','message','結案快照的租車狀態未確認，扣款待確認'));
  END LOOP;
  FOR r IN SELECT q FROM jsonb_array_elements(f->'special_work') q WHERE q->>'kind' NOT IN ('follow_along','learning') AND
   (q->>'driver_id'=d.id OR (q->>'kind'='breakdown_replacement' AND (
    EXISTS(SELECT 1 FROM jsonb_array_elements(f->'original_runs') o WHERE o->>'id'=q->>'run_id' AND o->>'driver_id'=d.id)
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(f->'deliveries') o WHERE o->>'run_id'=q->>'run_id' AND o->>'original_driver_id'=d.id)))) LOOP
   label:=CASE r->>'kind' WHEN 'attached_support' THEN '附屬支援' WHEN 'breakdown_replacement' THEN '故障接替' ELSE '特殊勤務' END;
   driver_issues:=driver_issues||jsonb_build_array(jsonb_build_object('code','special_pay','driverId',d.id,'date',r->>'service_date','source','special:'||(r->>'id'),'message',label||'計酬歸屬與金額待確認；不另增加配送總趟次'));
   lines:=lines||jsonb_build_array(jsonb_build_object('driverId',d.id,'date',r->>'service_date','source','special:'||(r->>'id'),'kind',r->>'kind','quantity',NULL,'ruleId',NULL,'amount',NULL,'closeEventId',r->'close_event_id','status',label||'待對帳'));
  END LOOP;
  FOR r IN SELECT q FROM jsonb_array_elements(f->'attendance_records') q WHERE q->>'driver_id'=d.id LOOP
   driver_issues:=driver_issues||jsonb_build_array(jsonb_build_object('code','attendance_exception','driverId',d.id,'date',r->>'service_date','source','attendance:'||(r->>'id'),'message','出勤例外／原始代碼對薪資的影響待確認'));
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_each_text(parts) WHERE abs(value::numeric)*100>9007199254740991) THEN RAISE EXCEPTION '對帳金額超出安全計算範圍';END IF;
  SELECT CASE WHEN count(value)=3 THEN sum(value::numeric) END INTO subtotal FROM jsonb_each_text(parts);
  IF abs(subtotal)*100>9007199254740991 THEN RAISE EXCEPTION '對帳金額超出安全計算範圍';END IF;
  SELECT jsonb_build_object(
   'count',(SELECT count(*) FROM jsonb_array_elements(f->'deliveries') q WHERE q->>'driver_id'=d.id),
   'standbyCount',(SELECT count(*) FROM jsonb_array_elements(f->'standby') q WHERE q->>'driver_id'=d.id AND NOT coalesce((q->>'converted_to_support')::boolean,false)),
   'followAlongCount',(SELECT count(*) FROM jsonb_array_elements(f->'special_work') q WHERE q->>'driver_id'=d.id AND q->>'kind'='follow_along'),
   'learningCount',(SELECT count(*) FROM jsonb_array_elements(f->'special_work') q WHERE q->>'driver_id'=d.id AND q->>'kind'='learning'),
   'rentalCount',(SELECT count(*) FROM jsonb_array_elements(f->'deliveries') q WHERE q->>'driver_id'=d.id AND q->>'is_rental'='true'),
   'unknownRentalCount',(SELECT count(*) FROM jsonb_array_elements(f->'deliveries') q WHERE q->>'driver_id'=d.id AND q->>'is_rental' IS NULL)) INTO counts;
  summaries:=summaries||jsonb_build_array(counts||jsonb_build_object('driverId',d.id,'name',d.name,'basis','route_management',
   'variable',parts->'per_run',
   'rentalDeduction',parts->'rental','adjustment',parts->'adjustment','basicSubtotal',subtotal,'salary',CASE WHEN subtotal IS NOT NULL AND jsonb_array_length(driver_issues)=0 THEN subtotal END,'salaryReady',subtotal IS NOT NULL AND jsonb_array_length(driver_issues)=0,'knownItemsReady',subtotal IS NOT NULL,'issues',driver_issues));
  issues:=issues||driver_issues;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(b->'expenses') LOOP
  issues:=issues||jsonb_build_array(jsonb_build_object('code','expense_treatment','driverId',coalesce(r->>'driver_id',''),'date',r->>'service_date','source','expense:'||(r->>'id'),'message','停車交通／零用金列為獨立費用；不自動併入薪資'));
 END LOOP;
 RETURN b||jsonb_build_object('calculation',jsonb_build_object('version',1415,'engine','database','month',to_char(p_month,'YYYY-MM'),
  'summaries',summaries,'lines',lines,'issues',issues,'expenses',b->'expenses','dates',f->'dates'));
END $function$

CREATE OR REPLACE FUNCTION public.dashboard_get_schedule_month(p_driver_id uuid, p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE answer jsonb;firstday date;
BEGIN
 PERFORM private.dashboard143_require_dispatcher();PERFORM private.dashboard143_require_driver(p_driver_id);
 IF p_month IS NULL THEN RAISE EXCEPTION '請指定月份';END IF;
 firstday:=date_trunc('month',p_month)::date;
 SELECT jsonb_agg(jsonb_build_object('date',g.d::date,'revision',coalesce(s.revision,0),'is_leave',coalesce(s.is_leave,false),
  'closed',private.dashboard146_is_closed(g.d::date),'has_runs',private.dashboard143_has_runs(g.d::date,p_driver_id),
  'has_plan_exception',coalesce(s.has_plan_exception,false),'template_revision',s.template_revision) ORDER BY g.d)
 INTO answer FROM generate_series(firstday::timestamp,firstday+interval '1 month'-interval '1 day',interval '1 day') g(d)
 LEFT JOIN public.attendance_driver_days s ON s.service_date=g.d::date AND s.driver_id=p_driver_id
 LEFT JOIN public.daily_attendance_closeouts c ON c.service_date=g.d::date;
 RETURN answer;
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_guard_attendance_slot_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE limit_slots integer;
BEGIN
 IF NEW.status::text='cancelled' THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND (OLD.service_date,OLD.driver_id,OLD.attendance_category,OLD.attendance_slot_index) IS NOT DISTINCT FROM
 (NEW.service_date,NEW.driver_id,NEW.attendance_category,NEW.attendance_slot_index) AND OLD.status::text<>'cancelled' THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND (OLD.attendance_category,OLD.attendance_slot_index) IS DISTINCT FROM
   (NEW.attendance_category,NEW.attendance_slot_index) AND EXISTS (
     SELECT 1 FROM public.trip_executions e WHERE e.run_id=OLD.id AND e.review_status='confirmed')
 THEN RAISE EXCEPTION '此趟次已確認，無法改動出勤類別或欄位';END IF;
 IF NEW.attendance_category IS NULL THEN RETURN NEW; END IF;
 IF NOT (SELECT private.is_dispatcher()) THEN RAISE EXCEPTION '只有主管可指定出勤欄位';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(NEW.service_date::text));
 SELECT COALESCE((SELECT c.slot_count FROM public.daily_attendance_slot_counts c
  WHERE c.service_date=NEW.service_date AND c.category=NEW.attendance_category),
  public.dashboard_attendance_slot_base(NEW.attendance_category)) INTO limit_slots;
 IF NEW.attendance_slot_index>limit_slots THEN
   RAISE EXCEPTION '此日期的%目前只有%趟；請先調整趟數',NEW.attendance_category,limit_slots;
 END IF;
 IF EXISTS (SELECT 1 FROM public.daily_attendance_extra_trips x
   WHERE x.service_date=NEW.service_date AND x.driver_id=NEW.driver_id
     AND x.attendance_category=NEW.attendance_category
     AND x.attendance_slot_index=NEW.attendance_slot_index AND x.status='active')
 THEN RAISE EXCEPTION '此欄位已有臨時實際趟次，請先處理該紀錄';END IF;
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_guard_attendance_slot_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE highest integer;
BEGIN
 IF NOT (SELECT private.is_dispatcher()) THEN RAISE EXCEPTION '只有主管可調整每日趟數'; END IF;
 IF TG_OP='UPDATE' AND (OLD.service_date,OLD.category) IS DISTINCT FROM (NEW.service_date,NEW.category)
 THEN RAISE EXCEPTION '不可變更已儲存出勤欄位設定的日期或類別';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(NEW.service_date::text));
 IF EXISTS (SELECT 1 FROM public.daily_attendance_closeouts c
   WHERE c.service_date=NEW.service_date AND c.closed_at IS NOT NULL)
 THEN RAISE EXCEPTION '此日期已結案，請先重新開啟';END IF;
 SELECT COALESCE(MAX(s),0) INTO highest FROM (
   SELECT MAX(attendance_slot_index) AS s FROM public.runs
    WHERE service_date=NEW.service_date AND attendance_category=NEW.category
     AND (status::text<>'cancelled' OR EXISTS(SELECT 1 FROM public.daily_run_observations o WHERE o.run_id=public.runs.id))
   UNION ALL
   SELECT MAX(attendance_slot_index) AS s FROM public.daily_attendance_extra_trips
    WHERE service_date=NEW.service_date AND attendance_category=NEW.category AND status='active'
 ) x;
 IF NEW.slot_count<highest THEN RAISE EXCEPTION '%第 % 趟已有資料，不可減少至 % 趟',NEW.category,highest,NEW.slot_count;END IF;
 NEW.updated_at:=now();NEW.updated_by:=auth.uid();RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_guard_closed_run_day()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old_date date; new_date date;
BEGIN
 IF TG_OP <> 'INSERT' THEN old_date:=OLD.service_date; END IF;
 IF TG_OP <> 'DELETE' THEN new_date:=NEW.service_date; END IF;
 IF old_date IS NOT NULL AND new_date IS NOT NULL AND old_date<>new_date THEN
   PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(LEAST(old_date,new_date)::text));
   PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(GREATEST(old_date,new_date)::text));
 ELSE
   PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(COALESCE(old_date,new_date)::text));
 END IF;
 IF (old_date IS NOT NULL AND EXISTS
   (SELECT 1 FROM public.daily_attendance_closeouts c WHERE c.service_date=old_date AND c.closed_at IS NOT NULL))
 OR (new_date IS NOT NULL AND EXISTS
   (SELECT 1 FROM public.daily_attendance_closeouts c WHERE c.service_date=new_date AND c.closed_at IS NOT NULL))
 THEN RAISE EXCEPTION '此出勤日期已結案；請先由主管重新開啟'; END IF;
 IF TG_OP='UPDATE' AND NOT private.dashboard146_write_allowed(OLD.id) AND EXISTS
    (SELECT 1 FROM public.trip_executions e WHERE e.run_id=OLD.id AND e.review_status='confirmed')
    AND (OLD.service_date,OLD.route_id,OLD.driver_id,OLD.vehicle_id,OLD.is_rental)
      IS DISTINCT FROM (NEW.service_date,NEW.route_id,NEW.driver_id,NEW.vehicle_id,NEW.is_rental)
 THEN RAISE EXCEPTION '此趟次已確認，不得修改已確認的預排欄位';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_guard_closeout_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT (SELECT private.is_dispatcher()) THEN RAISE EXCEPTION '只有主管可結案或重新開啟';END IF;
 IF TG_OP='UPDATE' AND OLD.service_date<>NEW.service_date THEN RAISE EXCEPTION '不可變更結案日期';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(NEW.service_date::text));
 RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_rename_driver(p_driver uuid, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
 IF NOT (SELECT private.is_dispatcher()) THEN RAISE EXCEPTION '只有主管可修改司機姓名';END IF;
 IF p_name IS NULL OR length(btrim(p_name)) NOT BETWEEN 1 AND 70 THEN RAISE EXCEPTION '請輸入司機姓名';END IF;
 UPDATE public.profiles SET display_name=btrim(p_name) WHERE id=p_driver AND role='driver';
 IF NOT FOUND THEN RAISE EXCEPTION '找不到司機帳號';END IF;
END$function$

CREATE OR REPLACE FUNCTION public.dashboard_reopen_attendance_date(p_date date, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE stamp timestamptz;event_id bigint;
BEGIN
 PERFORM private.dashboard143_lock();PERFORM private.dashboard143_require_dispatcher();
 IF p_date IS NULL OR nullif(btrim(coalesce(p_reason,'')),'') IS NULL OR length(p_reason)>1000
 THEN RAISE EXCEPTION '重新開啟必須填寫原因（1–1000 字）';END IF;
 IF NOT private.dashboard146_is_closed(p_date) THEN RAISE EXCEPTION '此日期尚未結案';END IF;
 stamp:=clock_timestamp();
 INSERT INTO public.attendance_closeout_events(action,through_date,actor_id,happened_at,reason,affected_dates)
 VALUES('reopen',p_date,auth.uid(),stamp,btrim(p_reason),ARRAY[p_date]) RETURNING id INTO event_id;
 INSERT INTO public.daily_attendance_closeouts(service_date,closed_at,closed_by,reopened_at,reopen_reason)
 VALUES(p_date,NULL,NULL,stamp,btrim(p_reason)) ON CONFLICT(service_date) DO UPDATE
 SET closed_at=NULL,closed_by=NULL,reopened_at=stamp,reopen_reason=btrim(p_reason);
 RETURN jsonb_build_object('event_id',event_id,'date',p_date,'reopened',true);
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_request_attendance_change(p_run_id bigint, p_extra_trip_id bigint, p_route_id bigint, p_vehicle_id bigint, p_note text, p_expected_revision integer, p_expected_observation_revision integer DEFAULT 0, p_void boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.runs%ROWTYPE;x public.daily_attendance_extra_trips%ROWTYPE;o public.daily_run_observations%ROWTYPE;
 d date;owner_id uuid;base jsonb;execution jsonb;request_row public.attendance_change_requests%ROWTYPE;
BEGIN
 PERFORM private.dashboard143_lock();
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND active AND role='driver')
 THEN RAISE EXCEPTION '只有司機可送出本人趟次變更' USING ERRCODE='42501';END IF;
 IF num_nonnulls(p_run_id,p_extra_trip_id)<>1 THEN RAISE EXCEPTION '請指定一筆配送紀錄';END IF;
 IF p_run_id IS NOT NULL THEN
  SELECT * INTO r FROM public.runs WHERE id=p_run_id FOR UPDATE;
  IF NOT FOUND OR r.driver_id<>auth.uid() THEN RAISE EXCEPTION '只能修改本人的趟次' USING ERRCODE='42501';END IF;
  IF r.status NOT IN ('assigned','in_progress','completed') THEN RAISE EXCEPTION '此趟次不能送出變更';END IF;
  IF coalesce(p_void,false) AND (r.status<>'assigned' OR EXISTS(SELECT 1 FROM public.trip_executions WHERE run_id=r.id))
  THEN RAISE EXCEPTION '只能申請取消尚未開始且沒有執行紀錄的趟次';END IF;
  SELECT * INTO o FROM public.daily_run_observations WHERE run_id=r.id;
  IF p_expected_revision IS NULL OR r.dashboard_schedule_revision<>p_expected_revision
   OR p_expected_observation_revision IS NULL OR coalesce(o.revision,0)<>p_expected_observation_revision
  THEN RAISE EXCEPTION '出勤資料已被更新，請重新整理';END IF;
  d:=r.service_date;owner_id:=r.driver_id;
  base:=jsonb_build_object('route_id',coalesce(o.actual_route_id,r.route_id),'vehicle_id',coalesce(o.actual_vehicle_id,r.vehicle_id),
   'note',coalesce(o.actual_note,r.dispatcher_notes,''),'status',r.status);
  SELECT to_jsonb(e) INTO execution FROM public.trip_executions e WHERE run_id=r.id;
 ELSE
  SELECT * INTO x FROM public.daily_attendance_extra_trips WHERE id=p_extra_trip_id FOR UPDATE;
  IF NOT FOUND OR x.driver_id<>auth.uid() THEN RAISE EXCEPTION '只能修改本人的趟次' USING ERRCODE='42501';END IF;
  IF x.status<>'active' OR p_expected_revision IS NULL OR x.revision<>p_expected_revision
  THEN RAISE EXCEPTION '臨時趟次已被更新，請重新整理';END IF;
  d:=x.service_date;owner_id:=x.driver_id;
  base:=jsonb_build_object('route_id',x.actual_route_id,'vehicle_id',x.actual_vehicle_id,'note',x.actual_note,'status',x.status);
 END IF;
 PERFORM private.dashboard143_open_day(d);
 IF NOT coalesce(p_void,false) AND (NOT EXISTS(SELECT 1 FROM public.routes WHERE id=p_route_id AND (active OR id=(base->>'route_id')::bigint))
  OR NOT EXISTS(SELECT 1 FROM public.vehicles WHERE id=p_vehicle_id AND (active OR id=(base->>'vehicle_id')::bigint)))
 THEN RAISE EXCEPTION '請選擇有效的路線與車輛';END IF;
 IF length(coalesce(p_note,''))>1000 OR (coalesce(p_void,false) AND nullif(btrim(coalesce(p_note,'')),'') IS NULL)
 THEN RAISE EXCEPTION '備註不可超過 1000 字；撤銷時需填寫原因';END IF;
 SELECT * INTO request_row FROM public.attendance_change_requests WHERE status='pending'
 AND ((p_run_id IS NOT NULL AND run_id=p_run_id) OR (p_extra_trip_id IS NOT NULL AND extra_trip_id=p_extra_trip_id)) FOR UPDATE;
 IF FOUND THEN
  IF request_row.source_revision=p_expected_revision AND request_row.observation_revision=coalesce(p_expected_observation_revision,0)
   AND request_row.proposed_route_id IS NOT DISTINCT FROM p_route_id AND request_row.proposed_vehicle_id IS NOT DISTINCT FROM p_vehicle_id
   AND request_row.proposed_note=coalesce(p_note,'') AND request_row.proposed_void=coalesce(p_void,false)
  THEN RETURN jsonb_build_object('id',request_row.id,'status','pending','revision',request_row.revision);END IF;
  RAISE EXCEPTION '此趟已有待審核變更，請先等待主管處理';
 END IF;
 INSERT INTO public.attendance_change_requests(run_id,extra_trip_id,service_date,driver_id,source_revision,observation_revision,
 base_record,base_execution,proposed_route_id,proposed_vehicle_id,proposed_note,proposed_void,requested_by)
 VALUES(p_run_id,p_extra_trip_id,d,owner_id,p_expected_revision,coalesce(p_expected_observation_revision,0),base,execution,
 p_route_id,p_vehicle_id,coalesce(p_note,''),coalesce(p_void,false),auth.uid()) RETURNING * INTO request_row;
 RETURN jsonb_build_object('id',request_row.id,'status','pending','revision',request_row.revision);
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_review_attendance_change(p_request_id bigint, p_expected_revision integer, p_approve boolean, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q public.attendance_change_requests%ROWTYPE;r public.runs%ROWTYPE;x public.daily_attendance_extra_trips%ROWTYPE;
 observation_version integer;execution jsonb;stale boolean:=false;problem text;result_id bigint;slot_extra_id bigint;
BEGIN
 PERFORM private.dashboard143_lock();PERFORM private.dashboard143_require_dispatcher();
 SELECT * INTO q FROM public.attendance_change_requests WHERE id=p_request_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION '找不到變更申請';END IF;
 IF q.status<>'pending' THEN RETURN jsonb_build_object('id',q.id,'status',q.status,'already_reviewed',true);END IF;
 IF p_expected_revision IS NULL OR q.revision<>p_expected_revision THEN RAISE EXCEPTION '申請已被更新，請重新整理';END IF;
 IF p_approve IS NULL OR length(coalesce(p_reason,''))>1000 THEN RAISE EXCEPTION '審核內容不正確';END IF;
 PERFORM private.dashboard143_open_day(q.service_date);
 IF NOT p_approve AND nullif(btrim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION '退回時請填寫原因';END IF;
 IF q.request_kind='duty' THEN RETURN private.dashboard1411_review(q,p_approve,p_reason);END IF;
 IF q.request_kind='standby' THEN RETURN private.dashboard1410_review(q,p_approve,p_reason);END IF;
 IF p_approve THEN
  IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=q.driver_id AND active AND role='driver') THEN
   stale:=true;
  ELSIF q.request_kind='add' THEN
   problem:=private.dashboard148_add_problem(q.service_date,q.driver_id,q.attendance_category,q.attendance_slot_index,q.source_revision,q.proposed_route_id,q.proposed_vehicle_id);
   SELECT id INTO slot_extra_id FROM public.daily_attendance_extra_trips WHERE service_date=q.service_date AND driver_id=q.driver_id AND attendance_category=q.attendance_category AND attendance_slot_index=q.attendance_slot_index;
   stale:=problem IS NOT NULL OR slot_extra_id IS DISTINCT FROM (q.base_record->>'previous_extra_id')::bigint;
   IF NOT stale THEN
    PERFORM public.dashboard_save_extra_actual_trip(q.service_date,q.driver_id,q.attendance_category,q.attendance_slot_index,q.proposed_route_id,q.proposed_vehicle_id,
     private.dashboard144_rental(q.service_date,q.driver_id,q.proposed_vehicle_id),q.proposed_note,q.source_revision,false);
    SELECT id INTO result_id FROM public.daily_attendance_extra_trips WHERE service_date=q.service_date AND driver_id=q.driver_id
     AND attendance_category=q.attendance_category AND attendance_slot_index=q.attendance_slot_index;
   END IF;
  ELSIF q.run_id IS NOT NULL THEN
   SELECT * INTO r FROM public.runs WHERE id=q.run_id FOR UPDATE;
   SELECT coalesce(max(revision),0) INTO observation_version FROM public.daily_run_observations WHERE run_id=q.run_id;
   SELECT to_jsonb(e) INTO execution FROM public.trip_executions e WHERE run_id=q.run_id;
   stale:=r.id IS NULL OR r.driver_id<>q.driver_id OR r.service_date<>q.service_date OR r.status NOT IN ('assigned','in_progress','completed')
    OR r.dashboard_schedule_revision<>q.source_revision OR observation_version<>q.observation_revision OR execution IS DISTINCT FROM q.base_execution
    OR (q.proposed_void AND (r.status<>'assigned' OR execution IS NOT NULL));
   IF NOT stale THEN PERFORM public.dashboard_edit_run_direct(q.run_id,q.proposed_route_id,q.proposed_vehicle_id,q.proposed_note,q.source_revision,q.observation_revision,q.proposed_void);END IF;
  ELSE
   SELECT * INTO x FROM public.daily_attendance_extra_trips WHERE id=q.extra_trip_id FOR UPDATE;
   stale:=x.id IS NULL OR x.driver_id<>q.driver_id OR x.service_date<>q.service_date OR x.revision<>q.source_revision OR x.status<>'active';
   IF NOT stale THEN PERFORM public.dashboard_save_extra_actual_trip(x.service_date,x.driver_id,x.attendance_category,x.attendance_slot_index,
    q.proposed_route_id,q.proposed_vehicle_id,private.dashboard144_rental(x.service_date,x.driver_id,q.proposed_vehicle_id),
    q.proposed_note,q.source_revision,q.proposed_void);END IF;
  END IF;
 END IF;
 UPDATE public.attendance_change_requests SET status=CASE WHEN stale THEN 'stale' WHEN p_approve THEN 'approved' ELSE 'rejected' END,
 result_extra_trip_id=coalesce(result_id,result_extra_trip_id),revision=revision+1,reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),
 review_reason=CASE WHEN stale THEN coalesce(problem,'原紀錄已變更；本次申請未套用，請重新送審') ELSE btrim(coalesce(p_reason,'')) END
 WHERE id=q.id RETURNING * INTO q;
 RETURN jsonb_build_object('id',q.id,'status',q.status,'reason',q.review_reason,'result_extra_trip_id',q.result_extra_trip_id);
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_save_actual_observation(p_run_id bigint, p_actual_route_id bigint, p_actual_vehicle_id bigint, p_note text, p_expected_revision integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE assigned public.runs%ROWTYPE; existing_revision integer; out_revision integer;
BEGIN
 PERFORM private.dashboard143_lock();
 IF NOT private.is_dispatcher() THEN RAISE EXCEPTION '司機修改趟次須先送出申請，經調度員核准後生效' USING ERRCODE='42501';END IF;
 IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.active)
 THEN RAISE EXCEPTION '請使用有效帳號登入';END IF;
 IF p_expected_revision IS NULL OR p_expected_revision<0 THEN RAISE EXCEPTION '編輯版本無效';END IF;
 SELECT * INTO assigned FROM public.runs WHERE id=p_run_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION '找不到配送趟次，請重新整理';END IF;
 IF NOT (SELECT private.is_dispatcher()) AND assigned.driver_id<>auth.uid()
 THEN RAISE EXCEPTION '無權修改其他司機的出勤';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(assigned.service_date::text));
 IF EXISTS (SELECT 1 FROM public.daily_attendance_closeouts
  WHERE service_date=assigned.service_date AND closed_at IS NOT NULL)
 THEN RAISE EXCEPTION '此出勤日期已結案';END IF;
 IF p_actual_route_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.routes WHERE id=p_actual_route_id)
 THEN RAISE EXCEPTION '找不到實際配送路線';END IF;
 IF p_actual_vehicle_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.vehicles WHERE id=p_actual_vehicle_id)
 THEN RAISE EXCEPTION '找不到實際使用車輛';END IF;
 IF length(COALESCE(p_note,''))>1000 THEN RAISE EXCEPTION '備註不可超過 1000 字';END IF;
 IF EXISTS (SELECT 1 FROM public.trip_executions e WHERE e.run_id=p_run_id AND e.review_status='confirmed')
 THEN RAISE EXCEPTION '此配送趟次已確認，須透過正式更正流程處理';END IF;
 SELECT revision INTO existing_revision FROM public.daily_run_observations WHERE run_id=p_run_id FOR UPDATE;
 IF p_expected_revision<>COALESCE(existing_revision,0) THEN RAISE EXCEPTION '資料已被其他人更新，請重新整理再編輯';END IF;
 IF existing_revision IS NULL THEN
   INSERT INTO public.daily_run_observations(run_id,driver_id,actual_route_id,actual_vehicle_id,actual_note,revision,updated_by)
    VALUES(p_run_id,assigned.driver_id,p_actual_route_id,p_actual_vehicle_id,COALESCE(p_note,''),1,auth.uid())
    RETURNING revision INTO out_revision;
 ELSE
   UPDATE public.daily_run_observations
   SET actual_route_id=p_actual_route_id,actual_vehicle_id=p_actual_vehicle_id,
       actual_note=COALESCE(p_note,''),revision=existing_revision+1,updated_by=auth.uid()
   WHERE run_id=p_run_id RETURNING revision INTO out_revision;
 END IF;
 RETURN out_revision;
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_save_day_plan(p_service_date date, p_driver_id uuid, p_category text, p_slot_index integer, p_route_id bigint, p_vehicle_id bigint, p_is_rental boolean, p_note text, p_run_id bigint, p_expected_run_revision integer, p_expected_day_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE oldrun public.runs%ROWTYPE;d public.attendance_driver_days%ROWTYPE;outid bigint;clean jsonb;
BEGIN
 PERFORM private.dashboard143_lock();PERFORM private.dashboard143_require_dispatcher();PERFORM private.dashboard143_require_driver(p_driver_id);
 PERFORM private.dashboard143_open_day(p_service_date);
 SELECT * INTO d FROM public.attendance_driver_days WHERE service_date=p_service_date AND driver_id=p_driver_id FOR UPDATE;
 IF p_expected_day_revision IS NULL OR coalesce(d.revision,0)<>p_expected_day_revision THEN RAISE EXCEPTION '此日出勤已被更新，請重新整理後再編輯';END IF;
 IF coalesce(d.is_leave,false) THEN RAISE EXCEPTION '該司機當日已標示「休」，請先取消休假';END IF;
 IF p_category IS NULL OR p_category NOT IN ('日配','OC','鮮二','冷凍','低鮮') OR p_slot_index IS NULL OR p_slot_index NOT BETWEEN 1 AND 30
 THEN RAISE EXCEPTION '請指定有效的出勤欄位';END IF;
 IF length(coalesce(p_note,''))>1000 THEN RAISE EXCEPTION '備註不可超過 1000 字';END IF;
 IF p_run_id IS NOT NULL THEN
  SELECT * INTO oldrun FROM public.runs WHERE id=p_run_id FOR UPDATE;
  IF NOT FOUND OR (oldrun.service_date,oldrun.driver_id) IS DISTINCT FROM (p_service_date,p_driver_id)
   OR p_expected_run_revision IS NULL OR oldrun.dashboard_schedule_revision<>p_expected_run_revision
  THEN RAISE EXCEPTION '預排趟次已被更新，請重新整理後再編輯';END IF;
  IF oldrun.status::text NOT IN ('assigned','cancelled') OR EXISTS(SELECT 1 FROM public.trip_executions WHERE run_id=oldrun.id)
  THEN RAISE EXCEPTION '此趟次已執行或送審，須透過既有更正流程處理';END IF;
 END IF;
 IF p_route_id IS NULL AND p_vehicle_id IS NULL AND oldrun.id IS NULL THEN RETURN jsonb_build_object('unchanged',true);END IF;
 IF d.applied_rows IS NULL THEN
  INSERT INTO public.attendance_driver_days(service_date,driver_id,applied_rows) VALUES(p_service_date,p_driver_id,private.dashboard143_day_snapshot(p_service_date,p_driver_id))
  ON CONFLICT(service_date,driver_id) DO UPDATE SET applied_rows=excluded.applied_rows;
 END IF;
 IF p_route_id IS NULL AND p_vehicle_id IS NULL THEN
  UPDATE public.runs SET status='cancelled',dispatcher_notes=nullif(btrim(coalesce(p_note,'')),'') WHERE id=oldrun.id;
  RETURN jsonb_build_object('run_id',oldrun.id,'cancelled',true);
 END IF;
 clean:=private.dashboard143_normalize_rows(jsonb_build_array(jsonb_build_object('category',p_category,'slot_index',p_slot_index,'route_id',p_route_id,'vehicle_id',p_vehicle_id,'is_rental',p_is_rental)));
 PERFORM private.dashboard143_check_conflict(p_service_date,p_driver_id,p_vehicle_id,p_route_id,oldrun.id);
 IF oldrun.id IS NULL THEN
  INSERT INTO public.runs(service_date,driver_id,route_id,vehicle_id,is_rental,status,dispatcher_notes,attendance_category,attendance_slot_index)
  VALUES(p_service_date,p_driver_id,p_route_id,p_vehicle_id,p_is_rental,'assigned',nullif(btrim(coalesce(p_note,'')),''),p_category,p_slot_index) RETURNING id INTO outid;
 ELSE
  UPDATE public.runs SET route_id=p_route_id,vehicle_id=p_vehicle_id,is_rental=p_is_rental,status='assigned',
   dispatcher_notes=nullif(btrim(coalesce(p_note,'')),''),attendance_category=p_category,attendance_slot_index=p_slot_index
  WHERE id=oldrun.id RETURNING id INTO outid;
 END IF;
 RETURN jsonb_build_object('run_id',outid,'cancelled',false);
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_save_day_template(p_driver_id uuid, p_rows jsonb, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE current_rev integer;clean jsonb;outrec public.driver_day_templates%ROWTYPE;
BEGIN
 PERFORM private.dashboard143_lock();PERFORM private.dashboard143_require_dispatcher();PERFORM private.dashboard143_require_driver(p_driver_id);
 SELECT revision INTO current_rev FROM public.driver_day_templates WHERE driver_id=p_driver_id FOR UPDATE;
 IF p_expected_revision IS NULL OR p_expected_revision<>coalesce(current_rev,0) THEN RAISE EXCEPTION '範本已被其他人更新，請重新載入';END IF;
 clean:=private.dashboard143_normalize_rows(p_rows);
 INSERT INTO public.driver_day_templates(driver_id,rows,revision,updated_by) VALUES(p_driver_id,clean,1,auth.uid())
 ON CONFLICT(driver_id) DO UPDATE SET rows=excluded.rows,revision=public.driver_day_templates.revision+1,updated_at=now(),updated_by=auth.uid() RETURNING * INTO outrec;
 RETURN to_jsonb(outrec);
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_save_driver_base_salary(p_driver_id uuid, p_amount numeric, p_effective_month date, p_reason text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE revision bigint; result public.driver_base_salaries;
BEGIN
 IF NOT coalesce(private.can_manage_finance(),false) THEN RAISE EXCEPTION '僅 Brian 可設定司機底薪';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_driver_id AND role='driver') THEN RAISE EXCEPTION '請選擇有效司機';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(1414,pg_catalog.hashtext(p_driver_id::text));
 SELECT coalesce(max(id),0) INTO revision FROM public.driver_base_salaries WHERE driver_id=p_driver_id;
 IF p_expected_revision IS DISTINCT FROM revision THEN RAISE EXCEPTION '底薪設定已變更，請重新整理後再操作';END IF;
 IF p_amount IS NULL OR NOT(p_amount>=0 AND p_amount<=10000000 AND p_amount=trunc(p_amount)) THEN RAISE EXCEPTION '底薪請輸入 0 至 10,000,000 的整數；無底薪請填 0';END IF;
 IF p_effective_month IS NULL OR p_effective_month NOT BETWEEN '1900-01-01' AND '9998-12-01' OR extract(day FROM p_effective_month)<>1 THEN RAISE EXCEPTION '請選擇有效生效月份';END IF;
 IF coalesce(length(btrim(p_reason)),0)=0 OR length(p_reason)>2000 THEN RAISE EXCEPTION '請填寫 1 至 2000 字的變更原因';END IF;
 INSERT INTO public.driver_base_salaries(driver_id,amount,effective_month,reason)
 VALUES(p_driver_id,p_amount,p_effective_month,btrim(p_reason)) RETURNING * INTO result;
 RETURN to_jsonb(result);
END $function$

CREATE OR REPLACE FUNCTION public.dashboard_save_duty_supplements(p_effective_from date, p_standby_amount numeric, p_rental_amount numeric, p_follow_along_amount numeric, p_learning_amount numeric, p_reason text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE revision bigint;c text;a numeric;
BEGIN
 IF NOT coalesce(private.can_manage_finance(),false) THEN RAISE EXCEPTION '僅 Brian 可設定勤務／租車';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(1491,1);
 SELECT coalesce(max(id),0) INTO revision FROM public.payroll_supplement_rates;
 IF p_expected_revision IS DISTINCT FROM revision THEN RAISE EXCEPTION '設定已變更，請重新整理後再操作';END IF;
 IF p_effective_from IS NULL OR p_effective_from NOT BETWEEN '1900-01-01' AND '9998-12-31' THEN RAISE EXCEPTION '請選擇有效生效日';END IF;
 IF coalesce(length(btrim(p_reason)),0)=0 OR length(p_reason)>2000 THEN RAISE EXCEPTION '請填寫 1 至 2000 字的變更原因';END IF;
 IF num_nonnulls(p_standby_amount,p_rental_amount,p_follow_along_amount,p_learning_amount)=0 THEN RAISE EXCEPTION '請至少填寫一項金額';END IF;
 FOR c,a IN SELECT * FROM (VALUES('standby',p_standby_amount),('rental',p_rental_amount),('follow_along',p_follow_along_amount),('learning',p_learning_amount)) v(component,amount) LOOP
  IF a IS NULL THEN CONTINUE;END IF;
  IF a<0 OR a>10000000 OR a<>trunc(a) THEN RAISE EXCEPTION '金額請輸入 0 至 10,000,000 的整數';END IF;
  INSERT INTO public.payroll_supplement_rates(component,amount,effective_from,reason) VALUES(c,a,p_effective_from,p_reason);
 END LOOP;
 RETURN jsonb_build_object('revision',(SELECT max(id) FROM public.payroll_supplement_rates));
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_save_extra_actual_trip(p_service_date date, p_driver_id uuid, p_category text, p_slot_index integer, p_route_id bigint, p_vehicle_id bigint, p_is_rental boolean, p_note text, p_expected_revision integer, p_void boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old_rec public.daily_attendance_extra_trips%ROWTYPE; n integer; resulting_revision integer;
BEGIN
 PERFORM private.dashboard143_lock();
 IF NOT private.is_dispatcher() THEN RAISE EXCEPTION '司機新增、刪除或修改趟次須先送出申請，經調度員核准後生效' USING ERRCODE='42501';END IF;
 PERFORM private.dashboard143_open_day(p_service_date);
 IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.active)
 THEN RAISE EXCEPTION '請使用有效帳號登入';END IF;
 IF NOT (SELECT private.is_dispatcher()) AND auth.uid()<>p_driver_id
 THEN RAISE EXCEPTION '只可填寫自己的出勤資料';END IF;
 IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=p_driver_id AND active AND role='driver')
 THEN RAISE EXCEPTION '此司機帳號不存在或未啟用';END IF;
 IF p_service_date IS NULL OR p_category IS NULL OR p_category NOT IN ('日配','OC','鮮二','冷凍','低鮮')
    OR p_slot_index IS NULL OR p_slot_index NOT BETWEEN 1 AND 30
 THEN RAISE EXCEPTION '出勤類別或欄位錯誤';END IF;
 IF p_expected_revision IS NULL OR p_expected_revision<0 THEN RAISE EXCEPTION '編輯版本無效';END IF;
 IF length(COALESCE(p_note,''))>1000 THEN RAISE EXCEPTION '備註不可超過 1000 字';END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(p_service_date::text));
 IF EXISTS (SELECT 1 FROM public.daily_attendance_closeouts
   WHERE service_date=p_service_date AND closed_at IS NOT NULL)
 THEN RAISE EXCEPTION '此出勤日期已結案';END IF;
 SELECT COALESCE((SELECT slot_count FROM public.daily_attendance_slot_counts
    WHERE service_date=p_service_date AND category=p_category),
    public.dashboard_attendance_slot_base(p_category)) INTO n;
 IF p_slot_index>n THEN RAISE EXCEPTION '此欄位已被移除，請重新整理';END IF;
 IF EXISTS(SELECT 1 FROM public.runs
   WHERE service_date=p_service_date AND driver_id=p_driver_id
     AND attendance_category=p_category AND attendance_slot_index=p_slot_index
     AND (status::text<>'cancelled' OR EXISTS(SELECT 1 FROM public.daily_run_observations o WHERE o.run_id=public.runs.id)))
 THEN RAISE EXCEPTION '此欄位已有預排趟次，不能建立臨時趟次';END IF;
 SELECT * INTO old_rec FROM public.daily_attendance_extra_trips
  WHERE service_date=p_service_date AND driver_id=p_driver_id AND attendance_category=p_category
   AND attendance_slot_index=p_slot_index FOR UPDATE;
 IF p_expected_revision<>COALESCE(old_rec.revision,0)
 THEN RAISE EXCEPTION '資料已被其他人更新，請重新整理再編輯';END IF;
 IF old_rec.id IS NOT NULL AND NOT private.is_dispatcher()
 THEN RAISE EXCEPTION '司機修改既有趟次必須先送出變更申請，經主管核准後生效';END IF;
 IF COALESCE(p_void,false) AND old_rec.id IS NULL THEN RAISE EXCEPTION '找不到可撤銷的臨時趟次';END IF;
 IF COALESCE(p_void,false) AND NULLIF(btrim(COALESCE(p_note,'')),'') IS NULL
 THEN RAISE EXCEPTION '撤銷臨時趟次需填寫原因';END IF;
 IF NOT COALESCE(p_void,false) THEN
   IF p_route_id IS NULL OR p_vehicle_id IS NULL OR p_is_rental IS NULL
   THEN RAISE EXCEPTION '臨時趟次請填寫實際路線、車號及租車狀態';END IF;
   IF NOT EXISTS(SELECT 1 FROM public.routes WHERE id=p_route_id)
    OR NOT EXISTS(SELECT 1 FROM public.vehicles WHERE id=p_vehicle_id)
   THEN RAISE EXCEPTION '實際路線或車輛不存在';END IF;
 END IF;
 IF old_rec.id IS NULL THEN
  INSERT INTO public.daily_attendance_extra_trips
   (service_date,driver_id,attendance_category,attendance_slot_index,actual_route_id,
    actual_vehicle_id,is_rental,actual_note,status,created_by,updated_by)
  VALUES(p_service_date,p_driver_id,p_category,p_slot_index,p_route_id,p_vehicle_id,p_is_rental,
    COALESCE(p_note,''),'active',auth.uid(),auth.uid()) RETURNING revision INTO resulting_revision;
 ELSE
  UPDATE public.daily_attendance_extra_trips SET
    actual_route_id=CASE WHEN p_void THEN actual_route_id ELSE p_route_id END,
    actual_vehicle_id=CASE WHEN p_void THEN actual_vehicle_id ELSE p_vehicle_id END,
    is_rental=CASE WHEN p_void THEN is_rental ELSE p_is_rental END,
    actual_note=COALESCE(p_note,''),status=CASE WHEN p_void THEN 'void' ELSE 'active' END,
    revision=old_rec.revision+1,updated_at=now(),updated_by=auth.uid()
  WHERE id=old_rec.id RETURNING revision INTO resulting_revision;
 END IF;
 RETURN resulting_revision;
END;$function$

CREATE OR REPLACE FUNCTION public.dashboard_save_payroll_config(p_driver_id uuid, p_pay_basis text, p_explanation text, p_expected jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE current_row public.payroll_configs; result_row public.payroll_configs;
BEGIN
 IF NOT coalesce(private.can_manage_finance(),false) THEN RAISE EXCEPTION '僅 Brian 可設定計薪'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(149,2);
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_driver_id AND role='driver' AND active) THEN RAISE EXCEPTION '請選擇啟用中的司機'; END IF;
 IF p_pay_basis IS NULL OR p_pay_basis NOT IN ('fixed_only','per_run_only','fixed_plus_run','manual') THEN RAISE EXCEPTION '計酬方式無效'; END IF;
 IF coalesce(length(btrim(p_explanation)),0)=0 OR length(p_explanation)>2000 THEN RAISE EXCEPTION '請填寫 1 至 2000 字的設定依據'; END IF;
 SELECT * INTO current_row FROM public.payroll_configs WHERE driver_id=p_driver_id FOR UPDATE;
 IF FOUND THEN
  IF p_expected IS DISTINCT FROM to_jsonb(current_row) THEN RAISE EXCEPTION '計酬設定已變更，請重新整理後再操作'; END IF;
  UPDATE public.payroll_configs SET pay_basis=p_pay_basis,explanation=btrim(p_explanation),updated_by=auth.uid() WHERE id=current_row.id RETURNING * INTO result_row;
 ELSE
  IF p_expected IS NOT NULL THEN RAISE EXCEPTION '計酬設定已變更，請重新整理後再操作'; END IF;
  INSERT INTO public.payroll_configs(driver_id,pay_basis,explanation,updated_by) VALUES(p_driver_id,p_pay_basis,btrim(p_explanation),auth.uid()) RETURNING * INTO result_row;
 END IF;
 RETURN to_jsonb(result_row);
END $function$

CREATE OR REPLACE FUNCTION public.dashboard_save_payroll_supplements(p_effective_from date, p_standby_amount numeric, p_rental_amount numeric, p_reason text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE revision bigint;
BEGIN
 IF NOT coalesce(private.can_manage_finance(),false) THEN RAISE EXCEPTION '僅 Brian 可設定值班／租車'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(1491,1);
 SELECT coalesce(max(id),0) INTO revision FROM public.payroll_supplement_rates;
 IF p_expected_revision IS DISTINCT FROM revision THEN RAISE EXCEPTION '設定已變更，請重新整理後再操作'; END IF;
 IF p_effective_from IS NULL OR p_effective_from NOT BETWEEN '1900-01-01' AND '9998-12-31' THEN RAISE EXCEPTION '請選擇有效生效日'; END IF;
 IF coalesce(length(btrim(p_reason)),0)=0 OR length(p_reason)>2000 THEN RAISE EXCEPTION '請填寫 1 至 2000 字的變更原因'; END IF;
 IF p_standby_amount IS NULL AND p_rental_amount IS NULL THEN RAISE EXCEPTION '請至少填寫一項金額'; END IF;
 IF (p_standby_amount IS NOT NULL AND (p_standby_amount<0 OR p_standby_amount>10000000 OR p_standby_amount<>trunc(p_standby_amount))) OR
    (p_rental_amount IS NOT NULL AND (p_rental_amount<0 OR p_rental_amount>10000000 OR p_rental_amount<>trunc(p_rental_amount))) THEN RAISE EXCEPTION '金額請輸入 0 至 10,000,000 的整數；租車費用會自動扣除'; END IF;
 IF p_standby_amount IS NOT NULL THEN INSERT INTO public.payroll_supplement_rates(component,amount,effective_from,reason) VALUES('standby',p_standby_amount,p_effective_from,p_reason); END IF;
 IF p_rental_amount IS NOT NULL THEN INSERT INTO public.payroll_supplement_rates(component,amount,effective_from,reason) VALUES('rental',p_rental_amount,p_effective_from,p_reason); END IF;
 RETURN jsonb_build_object('revision',(SELECT max(id) FROM public.payroll_supplement_rates));
END $function$

