CREATE OR REPLACE FUNCTION public.dashboard_set_attendance_slot_counts(p_service_date date, p_counts jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE grp text; n integer; raw text;
BEGIN
 PERFORM private.dashboard143_lock();
 IF NOT (SELECT private.is_dispatcher()) THEN RAISE EXCEPTION '只有主管可調整每日趟數'; END IF;
 IF p_service_date IS NULL OR p_counts IS NULL OR jsonb_typeof(p_counts)<>'object'
    OR (SELECT count(*) FROM jsonb_object_keys(p_counts))<>5 THEN
   RAISE EXCEPTION '請提供日期與五個配送類別的趟數';
 END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(p_service_date::text));
 IF EXISTS (SELECT 1 FROM public.daily_attendance_closeouts c
            WHERE c.service_date=p_service_date AND c.closed_at IS NOT NULL) THEN
    RAISE EXCEPTION '此日期已結案，請先重新開啟';
 END IF;
 FOREACH grp IN ARRAY ARRAY['日配','OC','鮮二','冷凍','低鮮'] LOOP
   raw:=p_counts->>grp;
   IF raw IS NULL OR raw !~ '^[0-9]{1,2}$' THEN
     RAISE EXCEPTION '類別 % 的趟數不是整數',grp;
   END IF;
   n:=raw::integer;
   IF n NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION '每日每類別僅可設定 1–30 趟'; END IF;
   INSERT INTO public.daily_attendance_slot_counts(service_date,category,slot_count)
     VALUES(p_service_date,grp,n)
   ON CONFLICT(service_date,category) DO UPDATE SET slot_count=excluded.slot_count;
 END LOOP;
END; $function$

CREATE OR REPLACE FUNCTION public.dashboard_set_driver_leave(p_service_date date, p_driver_id uuid, p_is_leave boolean, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.attendance_driver_days%ROWTYPE;
BEGIN
 PERFORM private.dashboard143_lock();PERFORM private.dashboard143_require_dispatcher();PERFORM private.dashboard143_require_driver(p_driver_id);
 PERFORM private.dashboard143_open_day(p_service_date);
 SELECT * INTO d FROM public.attendance_driver_days WHERE service_date=p_service_date AND driver_id=p_driver_id FOR UPDATE;
 IF p_is_leave IS NULL OR p_expected_revision IS NULL OR p_expected_revision<>coalesce(d.revision,0)
 THEN RAISE EXCEPTION '此日出勤已被更新，請重新整理後再設定休假';END IF;
 IF p_is_leave AND private.dashboard143_has_runs(p_service_date,p_driver_id)
 THEN RAISE EXCEPTION '此日已有預排或實際出勤趟次，無法標示「休」；系統不會自動刪除';END IF;
 INSERT INTO public.attendance_driver_days(service_date,driver_id,is_leave,revision,has_plan_exception,updated_by)
 VALUES(p_service_date,p_driver_id,p_is_leave,1,true,auth.uid()) ON CONFLICT(service_date,driver_id) DO UPDATE SET
 is_leave=excluded.is_leave,revision=public.attendance_driver_days.revision+1,has_plan_exception=true,updated_at=now(),updated_by=auth.uid() RETURNING * INTO d;
 RETURN to_jsonb(d);
END;$function$

CREATE OR REPLACE FUNCTION public.guard_daily_run_observation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE r record;
BEGIN
 SELECT driver_id,service_date INTO r FROM public.runs WHERE id=NEW.run_id;
 IF NOT FOUND THEN RAISE EXCEPTION '找不到配送趟次'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(20261019,pg_catalog.hashtext(r.service_date::text));
 IF NEW.driver_id IS DISTINCT FROM r.driver_id THEN RAISE EXCEPTION '不得修改其他司機的紀錄'; END IF;
 IF EXISTS (SELECT 1 FROM public.daily_attendance_closeouts c WHERE c.service_date=r.service_date AND c.closed_at IS NOT NULL)
 THEN RAISE EXCEPTION '此日期已結案'; END IF;
 IF NOT (SELECT private.is_dispatcher()) AND r.driver_id<>auth.uid() THEN RAISE EXCEPTION '無權修改該趟次'; END IF;
 NEW.updated_at:=now();NEW.updated_by:=auth.uid();RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.protect_run_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin

    -- Dispatchers may edit anything
    if (select private.is_dispatcher()) then
        return new;
    end if;

    -- Drivers may only edit their own run
    if old.driver_id != (select auth.uid()) then
        raise exception 'You cannot update this run.';
    end if;

    -- Drivers cannot change assignment information
    if new.driver_id is distinct from old.driver_id
       or new.vehicle_id is distinct from old.vehicle_id
       or new.route_id is distinct from old.route_id
       or new.service_date is distinct from old.service_date
       or new.scheduled_time is distinct from old.scheduled_time
       or new.dispatcher_notes is distinct from old.dispatcher_notes
    then
        raise exception 'Drivers cannot modify dispatch assignments.';
    end if;

    -- Drivers may only move through these statuses
    if new.status not in ('in_progress', 'completed') then
        raise exception 'Drivers may only start or complete a run.';
    end if;

    -- Assigned must be started first
    if old.status = 'assigned'
       and new.status not in ('assigned', 'in_progress')
    then
        raise exception 'An assigned run must be started before completion.';
    end if;

    -- In-progress may only stay in-progress or complete
    if old.status = 'in_progress'
       and new.status not in ('in_progress', 'completed')
    then
        raise exception 'An in-progress run may only be completed.';
    end if;

    return new;

end;
$function$

CREATE OR REPLACE FUNCTION public.route_catalog_rename_zone(p_old_name text, p_new_name text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE cleaned text := btrim(p_new_name);
BEGIN
  IF NOT (SELECT private.is_dispatcher()) THEN RAISE EXCEPTION '只有主管可以修改溫層'; END IF;
  IF cleaned IS NULL OR length(cleaned) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION '溫層名稱需為 1–50 字'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.delivery_temperature_zones WHERE name = p_old_name) THEN
    RAISE EXCEPTION '找不到原始溫層'; END IF;
  IF cleaned = p_old_name THEN RETURN; END IF;
  UPDATE public.delivery_temperature_zones SET name = cleaned WHERE name = p_old_name;
  UPDATE public.routes SET temperature_zone = cleaned WHERE temperature_zone = p_old_name;
END$function$

CREATE OR REPLACE FUNCTION public.v05512_reconcile_replacement_execution(p_work_id bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  w public.v055_run_work%rowtype;
  original public.runs%rowtype;
  execution public.trip_executions%rowtype;
  audit_id bigint;
  actor uuid:=auth.uid();
begin
  if actor is null or not private.is_dispatcher() then
    raise exception '僅主管可稽核校正故障接替實際歸屬';
  end if;
  if p_work_id is null then raise exception '缺少故障接替勤務編號'; end if;
  if length(btrim(coalesce(p_reason,'')))<10 or length(p_reason)>1000 then
    raise exception '請填寫至少 10 字、最多 1000 字的校正原因';
  end if;
  select * into w from public.v055_run_work
    where id=p_work_id for update;
  if not found or w.kind<>'breakdown_replacement' or w.review_status='rejected' then
    raise exception '找不到有效故障接替勤務';
  end if;
  if not exists (
    select 1 from public.v055_driver_work_completions c
    where c.work_id=w.id and c.driver_id=w.driver_id
  ) then raise exception '接替司機沒有完成回報'; end if;
  select * into original from public.runs where id=w.run_id for share;
  if not found or original.status<>'completed' then
    raise exception '原始主線尚未完成';
  end if;
  select * into execution from public.trip_executions
    where run_id=w.run_id for update;
  if not found or execution.review_status='rejected' then
    raise exception '找不到可校正的實際趟次（或已退回）';
  end if;
  if exists (
    select 1 from public.monthly_settlements ms
    where ms.month_start=date_trunc('month',execution.service_date)::date
      and ms.status='closed'
  ) then
    raise exception '此月已結算封存，不可直接校正；請使用正式月結更正流程';
  end if;
  if execution.driver_id=w.driver_id and execution.vehicle_id=w.vehicle_id then
    return jsonb_build_object('execution_id',execution.id,'state','already_correct');
  end if;
  if execution.driver_id is distinct from original.driver_id
     or execution.vehicle_id is distinct from original.vehicle_id then
    raise exception '實際趟次不是原派車快照，請先人工稽核；不可自動覆寫';
  end if;
  insert into public.v05512_execution_attribution_corrections(
    execution_id,replacement_work_id,original_driver_id,original_vehicle_id,
    corrected_driver_id,corrected_vehicle_id,explanation,corrected_by,correction_transaction_id
  ) values (
    execution.id,w.id,execution.driver_id,execution.vehicle_id,
    w.driver_id,w.vehicle_id,btrim(p_reason),actor,txid_current()
  ) returning id into audit_id;
  update public.trip_executions set driver_id=w.driver_id,vehicle_id=w.vehicle_id
    where id=execution.id;
  if not found then raise exception '校正失敗，未更新實際趟次'; end if;
  return jsonb_build_object('execution_id',execution.id,'audit_id',audit_id,'state','corrected');
end $function$

CREATE OR REPLACE FUNCTION public.v055_finalize_replacement(p_work_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.v055_run_work%rowtype;
        parent public.runs%rowtype;
begin
  if auth.uid() is null or not private.is_dispatcher() then
    raise exception '只有主管可以結束故障接替的原始趟次'; end if;
  select * into w from public.v055_run_work where id=p_work_id for update;
  if not found or w.kind<>'breakdown_replacement' or w.review_status<>'pending' then
    raise exception '無有效的待審核故障接替任務'; end if;
  if not exists(select 1 from public.v055_driver_work_completions c
      where c.work_id=w.id and c.driver_id=w.driver_id) then
    raise exception '接替司機尚未回報完成'; end if;
  select * into parent from public.runs where id=w.run_id for update;
  if parent.status not in ('assigned','in_progress') then
    raise exception '原始趟次必須仍在已指派／配送中狀態，請檢查是否已被其他人完成'; end if;
  if exists(select 1 from public.trip_executions e where e.run_id=parent.id) then
    raise exception '原始趟次已有實際執行紀錄，請先核對'; end if;
  update public.runs set status='completed' where id=w.run_id;
  -- Immutable audit of the supervisor reconciliation action.
  insert into public.v055_work_audit(table_name,source_id,action,old_record,new_record,actor)
  values('runs',parent.id,'FINALIZE_REPLACEMENT',
    jsonb_build_object('status',parent.status,'scheduled_driver_id',parent.driver_id),
    jsonb_build_object('status','completed','replacement_work_id',w.id,
                       'replacement_driver_id',w.driver_id,'replacement_vehicle_id',w.vehicle_id),
    auth.uid());
  return jsonb_build_object('run_id',parent.id,'state','pending_execution_review');
end $function$

CREATE OR REPLACE FUNCTION public.v055_submit_special_completion(p_work_id bigint, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.v055_run_work%rowtype;
        parent public.runs%rowtype;
        worker uuid:=auth.uid();
begin
  if worker is null or not exists(
      select 1 from public.profiles p where p.id=worker and p.role='driver' and p.active
  ) then raise exception '只有有效司機可以回報勤務完成'; end if;
  if p_work_id is null then raise exception '無效的特殊勤務編號'; end if;
  if length(coalesce(p_note,''))>2000 then raise exception '完成備註不得超過 2000 字'; end if;
  select * into w from public.v055_run_work where id=p_work_id for update;
  if not found or w.driver_id<>worker or w.review_status<>'pending' then
    raise exception '此勤務不是目前帳號可回報的待審核任務'; end if;
  select * into parent from public.runs where id=w.run_id for share;
  if not found or parent.status='cancelled' then raise exception '關聯主線已取消，請聯絡主管'; end if;
  if w.kind='breakdown_replacement' and parent.status='completed' then
    raise exception '原始趟次已完成，請主管核對是否已處理接替'; end if;
  if exists(select 1 from public.v055_driver_work_completions c where c.work_id=w.id) then
    raise exception '此勤務已回報完成，不可重複提交'; end if;
  insert into public.v055_driver_work_completions(work_id,driver_id,completion_note)
     values(w.id,worker,btrim(coalesce(p_note,'')));
  return jsonb_build_object('work_id',w.id,'run_id',w.run_id,'state','submitted');
end $function$
